///
/// Two extractors are provided:
///
/// `AuthSession`   — validates the Bearer token, enforces inactivity timeout,
///                   and refreshes `last_activity_at` on every successful call.
///                   Use as a handler parameter for any authenticated endpoint.
///
/// `ReauthGuard`   — wraps `AuthSession` and additionally verifies that the user
///                   has re-authenticated within the configured reauth window.
///                   Use as a handler parameter for admin-action endpoints.
///
/// Token scheme:
///   Client sends `Authorization: Bearer <64-char-hex-token>`
///   Server stores SHA-256(token) as `token_hash` — the raw token never touches disk.
use std::{future::Future, pin::Pin};

use actix_web::{dev::Payload, web, FromRequest, HttpRequest};
use chrono::{DateTime, Duration, Utc};
use sha2::{Digest, Sha256};
use uuid::Uuid;

use crate::{auth::models::SessionRow, error::AppError, AppState};

// ============================================================
// AuthSession — validated session context attached to a request
// ============================================================

#[derive(Clone)]
pub struct AuthSession {
    pub session_id:       Uuid,
    pub user_id:          Uuid,
    pub username:         String,
    pub role:             String,
    pub expires_at:       DateTime<Utc>,
    pub last_activity_at: DateTime<Utc>,
    pub last_reauth_at:   Option<DateTime<Utc>>,
}

impl FromRequest for AuthSession {
    type Error  = AppError;
    type Future = Pin<Box<dyn Future<Output = Result<Self, Self::Error>>>>;

    fn from_request(req: &HttpRequest, _payload: &mut Payload) -> Self::Future {
        let req = req.clone();
        Box::pin(async move {
            let state = req
                .app_data::<web::Data<AppState>>()
                .cloned()
                .ok_or_else(|| AppError::Internal("App state not configured".to_string()))?;

            let token      = extract_bearer_token(&req)?;
            let token_hash = hash_token(&token);

            // ----------------------------------------------------------
            // 1. Load session row (JOIN users + roles for user context)
            // ----------------------------------------------------------
            let row = sqlx::query_as::<_, SessionRow>(
                r#"
                SELECT s.id, s.user_id, s.expires_at, s.revoked_at,
                       s.last_activity_at, s.last_reauth_at,
                       u.username, r.name AS role_name
                FROM   auth.sessions s
                JOIN   auth.users u ON u.id = s.user_id
                JOIN   auth.roles r ON r.id = u.role_id
                WHERE  s.token_hash = $1
                  AND  u.deleted_at IS NULL
                "#,
            )
            .bind(&token_hash)
            .fetch_optional(&state.db)
            .await
            .map_err(AppError::Database)?
            .ok_or_else(|| AppError::Unauthorized("Invalid or expired token".to_string()))?;

            // ----------------------------------------------------------
            // 2. Revocation check
            // ----------------------------------------------------------
            if row.revoked_at.is_some() {
                return Err(AppError::Unauthorized("Session has been revoked".to_string()));
            }

            // ----------------------------------------------------------
            // 3. Absolute expiry check
            // ----------------------------------------------------------
            if row.expires_at < Utc::now() {
                return Err(AppError::Unauthorized("Session has expired".to_string()));
            }

            // ----------------------------------------------------------
            // 4. Inactivity timeout — revoke and reject if idle too long
            // ----------------------------------------------------------
            let idle_limit = Duration::minutes(state.config.inactivity_timeout_minutes);
            if Utc::now() - row.last_activity_at > idle_limit {
                // Eagerly revoke the idle session so subsequent calls also fail fast.
                let _ = sqlx::query(
                    "UPDATE auth.sessions SET revoked_at = now() WHERE id = $1",
                )
                .bind(row.id)
                .execute(&state.db)
                .await;

                return Err(AppError::Unauthorized(
                    "Session expired due to inactivity. Please log in again.".to_string(),
                ));
            }

            // ----------------------------------------------------------
            // 5. Refresh last_activity_at (fire-and-forget; failure is non-fatal)
            // ----------------------------------------------------------
            let _ = sqlx::query(
                "UPDATE auth.sessions SET last_activity_at = now() WHERE id = $1",
            )
            .bind(row.id)
            .execute(&state.db)
            .await;

            Ok(AuthSession {
                session_id:       row.id,
                user_id:          row.user_id,
                username:         row.username,
                role:             row.role_name,
                expires_at:       row.expires_at,
                last_activity_at: Utc::now(),
                last_reauth_at:   row.last_reauth_at,
            })
        })
    }
}

// ============================================================
// ReauthGuard — AuthSession + recent re-auth verification
// ============================================================

