    .bind(route_id)
    .execute(&state.db)
    .await?
    .rows_affected();

    if affected == 0 {
        return Err(AppError::BadRequest(format!("Route {} not found", route_id)));
    }

    Ok(HttpResponse::Ok().json(OkResponse { message: "Route deleted" }))
}

/// POST /ops/routes/{id}/publish
