/// Interval overlap: [a_dep, a_arr) ∩ [b_dep, b_arr) ≠ ∅
///   ⟺  a_dep < b_arr  AND  a_arr > b_dep
async fn detect_driver_overlap(
    pool:      &PgPool,
    trip:      &TripCheckInput,
    driver_id: Uuid,
) -> Result<Vec<ConflictDetail>, sqlx::Error> {
    #[derive(sqlx::FromRow)]
