/// GET /dispatcher/monitor/upcoming?window_minutes=120
pub async fn upcoming_trips(
    state:   web::Data<AppState>,
    session: AuthSession,
    query:   web::Query<UpcomingQuery>,
) -> Result<HttpResponse, AppError> {
