        ),
    )
    .bind(window)
    .fetch_all(&state.db)
    .await?;

    let mut trips = Vec::new();
    for row in rows {
        trips.push(to_summary(row, &state.db).await);
    }

    Ok(HttpResponse::Ok().json(json!({ "window_minutes": window, "trips": trips })))
}

