use serde::{Deserialize, Serialize};
use uuid::Uuid;

// ============================================================
// Request bodies
// ============================================================

#[derive(Deserialize)]
pub struct DeliveryQuery {
    /// `unread` (default) | `read` | `dismissed` | `all`
    pub status: Option<String>,
    pub limit:  Option<i64>,
    pub offset: Option<i64>,
}

#[derive(Deserialize)]
pub struct UpdatePreferencesRequest {
    pub dnd_enabled: bool,
    /// UTC time to start DND (e.g. "22:00:00"). Required when dnd_enabled = true
    /// and a time window is desired; omit for all-day DND.
    pub dnd_start:   Option<NaiveTime>,
    pub dnd_end:     Option<NaiveTime>,
}

#[derive(Deserialize)]
pub struct UpdateSubscriptionsRequest {
    /// Complete replacement of the user's subscriptions.
    /// Pass an empty list to unsubscribe from everything.
    pub event_types: Vec<String>,
}

#[derive(Deserialize)]
pub struct AnnounceRequest {
    pub title:   String,
    pub message: String,
    /// `info` | `warning` | `critical`  (default: `info`)
    /// `critical` bypasses all recipients' DND settings.
    pub severity:     Option<String>,
    /// Restrict delivery to users with these role names.
    /// `null` or `["all"]` means every active user receives it.
    pub target_roles: Option<Vec<String>>,
}

// ============================================================
// Response types
// ============================================================

#[derive(Serialize)]
pub struct DeliveryResponse {
    pub id:               Uuid,
    pub event_id:         Uuid,
    pub event_type:       String,
    /// Effective severity: payload override if present, else event_definitions default.
    pub severity:         String,
    pub source_entity_id: Option<Uuid>,
