{"file_path": "C:\Users\user\Desktop\eaglepoint_new\Week-2\TASK-62\repo\src\notifications\bus.rs", "content": "/// Event fan-out bus.
///
/// Architecture
/// ────────────
///   1.  The dispatcher (and other modules) write to `notifications.events`
///       via the thin `emit` helper — fire-and-forget, no fan-out logic there.
///
///   2.  A Tokio background task runs `run_event_bus` continuously.
///       Every 5 s it calls `process_pending_events`, which:
///         a. Selects up to 50 rows WHERE processed_at IS NULL (FIFO).
///         b. For each event, resolves the effective severity
///            (payload `"severity"` key overrides the event_definitions default).
///         c. Resolves recipients:
///              - `sys.announcement`  → all active users (or role-filtered subset)
///              - everything else      → users subscribed to that event_type
///         d. For each recipient:
///              i.  Skip if the event was triggered by this user (no self-notify).
///             ii.  Skip if DND is active AND severity != "critical".
///            iii.  Skip if a delivery for the same (user, event_type, entity)
///                  exists within the last 15 minutes (deduplication).
///             iv.  INSERT delivery row (ON CONFLICT DO NOTHING for idempotency).
///         e. Marks the event processed_at = now().
///            If fan-out fails, the event stays unprocessed and will be retried.
use chrono::{NaiveTime, Utc};
use serde_json::Value;
use sqlx::PgPool;
use std::time::Duration;
use uuid::Uuid;

// ── Internal row type ─────────────────────────────────────────────────────────

#[derive(sqlx::FromRow)]
struct PendingEventRow {
    id:                 Uuid,
    event_type:         String,
    source_entity_id:   Option<Uuid>,
    actor_id:           Option<Uuid>,
    payload:            Value,
    /// COALESCE(payload->>'severity', event_definitions.severity, 'info')
    effective_severity: String,
}

// ── Public API ────────────────────────────────────────────────────────────────

/// Spawn once in `main()` before starting the HTTP server.
///
/// ```rust
/// tokio::spawn(notifications::bus::run_event_bus(pool.clone()));
/// ```
pub async fn run_event_bus(pool: PgPool) {
    let interval = Duration::from_secs(5);
    loop {
        match process_pending_events(&pool).await {
            Ok(n) if n > 0 => tracing::info!(count = n, "Event bus: fan-out complete"),
            Ok(_)          => {}
            Err(e)         => tracing::error!("Event bus error: {}", e),
        }
        tokio::time::sleep(interval).await;
    }
}

/// Process one batch of up to 50 pending events.
/// Returns the number of events successfully processed.
pub async fn process_pending_events(pool: &PgPool) -> Result<usize, sqlx::Error> {
    let events = sqlx::query_as::<_, PendingEventRow>(
        r#"
        SELECT e.id,
               e.event_type,
               e.source_entity_id,
               e.actor_id,
               e.payload,
               COALESCE(
                   NULLIF(e.payload->>'severity', ''),
                   ed.severity,
                   'info'
               ) AS effective_severity
        FROM   notifications.events e
        JOIN   notifications.event_definitions ed ON ed.event_type = e.event_type
        WHERE  e.processed_at IS NULL
        ORDER  BY e.created_at ASC
        LIMIT  50
        "#,
    )
    .fetch_all(pool)
    .await?;

    let count = events.len();

    for event in &events {
        if let Err(e) = fan_out_event(pool, event).await {
            tracing::error!(
                event_id   = %event.id,
                event_type = %event.event_type,
                "Fan-out failed — will retry on next poll: {}",
                e
            );
            continue; // leave processed_at NULL so it's retried
        }

        sqlx::query(
            "UPDATE notifications.events SET processed_at = now() WHERE id = $1",
        )
        .bind(event.id)
        .execute(pool)
        .await?;
    }

    Ok(count)
}

// ── Fan-out logic ─────────────────────────────────────────────────────────────

async fn fan_out_event(pool: &PgPool, event: &PendingEventRow) -> Result<(), sqlx::Error> {
    let severity  = event.effective_severity.as_str();
    let recipients = get_recipients(pool, event).await?;

    for user_id in recipients {
        // Do not send a notification to the user who triggered the event
        if event.actor_id == Some(user_id) {
            continue;
        }

        // DND check — critical severity bypasses it
        if severity != "critical" && check_dnd(pool, user_id).await? {
            tracing::debug!(
                %user_id,
                event_type = %event.event_type,
                "Delivery suppressed: DND active"
            );
            continue;
        }

        // 15-minute deduplication window
        if check_duplicate(pool, user_id, &event.event_type, event.source_entity_id).await? {
            tracing::debug!(
                %user_id,
                event_type = %event.event_type,
                "Delivery suppressed: duplicate within 15-min window"
            );
            continue;
        }

        // Insert delivery (idempotent)
        sqlx::query(
            r#"
            INSERT INTO notifications.deliveries
                (event_id, user_id, status, delivered_at)
            VALUES ($1, $2, 'delivered', now())
            ON CONFLICT (event_id, user_id) DO NOTHING
            "#,
        )
        .bind(event.id)
        .bind(user_id)
        .execute(pool)
        .await?;
    }

    Ok(())
}

/// Resolve the set of users who should receive this event.
///
/// `sys.announcement` fans out to all active users (or a role-filtered subset).
/// All other event types deliver only to subscribed users.
async fn get_recipients(pool: &PgPool, event: &PendingEventRow) -> Result<Vec<Uuid>, sqlx::Error> {
    if event.event_type == "sys.announcement" {
        let target_roles: Option<Vec<String>> = event
            .payload
            .get("target_roles")
            .and_then(|v| v.as_array())
            .map(|arr| {
                arr.iter()
                    .filter_map(|v| v.as_str().map(String::from))
                    .collect()
            });

        let is_all = target_roles
            .as_deref()
            .map_or(true, |r| r.is_empty() || r == ["all"]);

        if is_all {
            sqlx::query_scalar(
                "SELECT id FROM auth.users WHERE is_active = TRUE AND deleted_at IS NULL",
            )
            .fetch_all(pool)
            .await
        } else {
            let roles = target_roles.unwrap();
            sqlx::query_scalar(
                r#"
                SELECT u.id
                FROM   auth.users u
                JOIN   auth.roles r ON r.id = u.role_id
                WHERE  u.is_active  = TRUE
                  AND  u.deleted_at IS NULL
                  AND  r.name       = ANY($1)
                "#,
            )
            .bind(&roles)
            .fetch_all(pool)
            .await
        }
    } else {
        sqlx::query_scalar(
            "SELECT user_id FROM notifications.subscriptions WHERE event_type = $1",
        )
        .bind(&event.event_type)
        .fetch_all(pool)
        .await
    }
}

/// Returns `true` if the user's DND window is currently active (UTC).
async fn check_dnd(pool: &PgPool, user_id: Uuid) -> Result<bool, sqlx::Error> {
    #[derive(sqlx::FromRow)]
    struct PrefRow {
        dnd_enabled: bool,
        dnd_start:   Option<NaiveTime>,
        dnd_end:     Option<NaiveTime>,
    }

    let pref = sqlx::query_as::<_, PrefRow>(
        r#"
        SELECT dnd_enabled, dnd_start, dnd_end
        FROM   notifications.preferences
        WHERE  user_id = $1
        "#,
    )
    .bind(user_id)
    .fetch_optional(pool)
    .await?;

    Ok(match pref {
        None                          => false,
        Some(p) if !p.dnd_enabled     => false,
        Some(PrefRow { dnd_start: Some(start), dnd_end: Some(end), .. }) => {
            let now = Utc::now().naive_utc().time();
            if start <= end {
                now >= start && now <= end      // e.g. 08:00–18:00
            } else {
                now >= start || now <= end      // crosses midnight e.g. 22:00–07:00
            }
        }
        _ => true, // dnd_enabled with no window set → all-day DND
    })
}

/// Returns `true` if a non-dismissed delivery for the same
/// (user, event_type, entity_id) triple already exists within the last 15 minutes.
async fn check_duplicate(
    pool:             &PgPool,
    user_id:          Uuid,
    event_type:       &str,
    source_entity_id: Option<Uuid>,
) -> Result<bool, sqlx::Error> {
    sqlx::query_scalar(
        r#"
        SELECT EXISTS (
            SELECT 1
            FROM   notifications.deliveries d
            JOIN   notifications.events     e ON e.id = d.event_id
            WHERE  d.user_id         = $1
              AND  e.event_type      = $2
              AND  (
                    ($3::UUID IS NULL AND e.source_entity_id IS NULL)
                 OR e.source_entity_id = $3
              )
              AND  d.created_at      > now() - interval '15 minutes'
              AND  d.status         != 'dismissed'
        )
        "#,
    )
    .bind(user_id)
    .bind(event_type)
    .bind(source_entity_id)
    .fetch_one(pool)
    .await
}
"}

