        .map(|r| SubscriptionInfo {
            subscribed: subscribed.contains(&r.event_type),
            event_type:  r.event_type,
            description: r.description,
            severity:    r.severity,
        })
        .collect();

    Ok(HttpResponse::Ok().json(resp))
}

/// PUT /notifications/subscriptions
///
/// Bulk-replace the caller's subscriptions.
/// Body: `{ "event_types": ["ops.trip.conflict_detected", "ops.trip.start_approaching"] }`
pub async fn update_subscriptions(
    state:   web::Data<AppState>,
    session: AuthSession,
    body:    web::Json<UpdateSubscriptionsRequest>,
) -> Result<HttpResponse, AppError> {
    session.require(Permission::NotificationsSubscriptionsManage)?;

    // Validate all provided event types exist (single query)
    if !body.event_types.is_empty() {
        let valid: Vec<String> = sqlx::query_scalar(
            "SELECT event_type FROM notifications.event_definitions WHERE event_type = ANY($1)",
        )
        .bind(&body.event_types)
        .fetch_all(&state.db)
        .await?;

        let unknown: Vec<&str> = body.event_types
            .iter()
            .filter(|et| !valid.contains(et))
            .map(String::as_str)
            .collect();

        if !unknown.is_empty() {
            return Err(AppError::BadRequest(
                format!("Unknown event type(s): {}", unknown.join(", ")),
            ));
        }
    }

    // Atomic bulk-replace inside a transaction
    let mut tx = state.db.begin().await?;

    sqlx::query("DELETE FROM notifications.subscriptions WHERE user_id = $1")
        .bind(session.user_id)
        .execute(&mut *tx)
        .await?;

    for et in &body.event_types {
        sqlx::query(
            r#"
            INSERT INTO notifications.subscriptions (user_id, event_type)
            VALUES ($1, $2)
            ON CONFLICT (user_id, event_type) DO NOTHING
            "#,
        )
        .bind(session.user_id)
        .bind(et)
        .execute(&mut *tx)
        .await?;
    }

    tx.commit().await?;

    Ok(HttpResponse::Ok().json(json!({
        "message": "Subscriptions updated",
        "count":   body.event_types.len(),
    })))
}

// ============================================================
// Announcements
// ============================================================

/// POST /notifications/announce
///
/// Broadcasts a system announcement. Requires `SysAnnouncementWrite`.
/// Immediately triggers the bus so delivery is synchronous within the request.
///
/// Body:
/// ```json
/// {
///   "title":        "Planned maintenance",
///   "message":      "System will be read-only from 02:00–03:00 UTC.",
///   "severity":     "warning",
///   "target_roles": ["dispatcher", "operations_admin"]
/// }
/// ```
///
/// `target_roles` is optional; omit (or pass `["all"]`) to reach every active user.
pub async fn announce(
    state:   web::Data<AppState>,
    session: AuthSession,
    body:    web::Json<AnnounceRequest>,
) -> Result<HttpResponse, AppError> {
    session.require(Permission::SysAnnouncementWrite)?;

    let severity = body.severity.as_deref().unwrap_or("info");
    if !["info", "warning", "critical"].contains(&severity) {
        return Err(AppError::BadRequest(
            "severity must be one of: info, warning, critical".to_string(),
        ));
    }

    if body.title.trim().is_empty() || body.message.trim().is_empty() {
        return Err(AppError::BadRequest(
            "title and message are required".to_string(),
        ));
    }

    let payload = serde_json::json!({
        "title":        body.title.trim(),
        "message":      body.message.trim(),
        "severity":     severity,
        "target_roles": body.target_roles,
    });

    // Persist event (FK to event_definitions requires the type to exist — seeded in 004)
    let event_id: Uuid = sqlx::query_scalar(
        r#"
        INSERT INTO notifications.events
            (event_type, source_domain, actor_id, payload)
        VALUES ('sys.announcement', 'sys', $1, $2)
        RETURNING id
        "#,
    )
    .bind(session.user_id)
    .bind(&payload)
    .fetch_one(&state.db)
    .await?;

    tracing::info!(
        %event_id,
        actor    = %session.user_id,
        severity,
        "Announcement broadcast initiated"
    );

    // Trigger immediate fan-out rather than waiting up to 5 s for the background bus.
    // The bus will skip this event on its next poll since processed_at will be set.
    let processed = bus::process_pending_events(&state.db).await.unwrap_or(0);

    Ok(HttpResponse::Ok().json(json!({
        "event_id":         event_id,
        "events_processed": processed,
        "message":          "Announcement broadcast",
    })))
}
"}

