1	use actix_web::{web, App, HttpServer};
2	use dotenvy::dotenv;
3	use tracing_subscriber::{fmt, prelude::*, EnvFilter};
4	
5	mod auth;
6	mod config;
7	mod db;
8	mod dispatcher;
9	mod error;
10	mod notifications;
11	mod ops;
12	mod rbac;
13	
14	/// Shared application state — cloned cheaply via `Arc` inside `web::Data`.
15	pub struct AppState {
16	    pub db:     sqlx::PgPool,
17	    pub config: config::Config,
18	}
19	
20	#[tokio::main]
21	async fn main() -> std::io::Result<()> {
22	    // Load .env (ignored if absent — production uses real env vars)
23	    dotenv().ok();
24	
25	    // Structured logging; set RUST_LOG=info or RUST_LOG=debug to control verbosity
26	    tracing_subscriber::registry()
27	        .with(fmt::layer())
28	        .with(EnvFilter::from_default_env())
29	        .init();
30	
31	    let cfg  = config::Config::from_env();
32	    let pool = db::create_pool(&cfg.database_url)
33	        .await
34	        .expect("Failed to connect to PostgreSQL");
35	
36	    let bind_addr = format!("{}:{}", cfg.server_host, cfg.server_port);
37	    tracing::info!("TransitOps backend listening on http://{}", bind_addr);
38	
39	    let state = web::Data::new(AppState { db: pool.clone(), config: cfg });
40	
41	    // Background event bus — polls every 5 s and fans out unprocessed events.
42	    // Must be spawned before the HTTP server so it starts processing immediately.
43	    tokio::spawn(notifications::bus::run_event_bus(pool));
44	
45	    HttpServer::new(move || {
46	        App::new()
47	            .app_data(state.clone())
48	            // Reject payloads larger than 64 KiB for auth endpoints
49	            .app_data(web::JsonConfig::default().limit(65_536))
50	            .configure(auth::configure_routes)
51	            .configure(ops::configure_routes)
52	            .configure(dispatcher::configure_routes)
53	            .configure(notifications::configure_routes)
54	    })
55	    .bind(&bind_addr)?
56	    .run()
57	    .await
58	}
59	
