use yew::prelude::*;

use components::{
    inbox_panel::InboxPanel,
    notification_badge::NotificationBadge,
};
use store::notification_store::InboxContextProvider;

/// Root application shell.
///
/// `InboxContextProvider` wraps the whole tree so that both `NotificationBadge`
/// (in the header) and `InboxPanel` (rendered as a portal-style overlay) can
/// share a single source of notification state via Yew's Context API.
#[function_component(App)]
fn app() -> Html {
    html! {
        <InboxContextProvider>
            // In a real application the badge would live inside an existing
            // header component.  It is shown here at the top level to
            // illustrate the integration point.
            <header class="app-header">
                <span class="app-header__brand">{ "TransitOps" }</span>
                <div class="app-header__actions">
                    <NotificationBadge />
                </div>
            </header>

            // InboxPanel renders nothing (html! {}) when closed; when open it
            // covers the viewport with an overlay + slide-in drawer.
            <InboxPanel />
        </InboxContextProvider>
    }
}

fn main() {
    console_log::init_with_level(log::Level::Debug)
        .expect("failed to init console_log");
    yew::Renderer::<App>::new().render();
}
"}

