        use chrono::TimeZone;
        let p = TimeSeriesPoint {
            period_start:  Utc.with_ymd_and_hms(2025, 1, 1, 0, 0, 0).unwrap(),
            period_end:    Utc.with_ymd_and_hms(2025, 1, 2, 0, 0, 0).unwrap(),
            value:         75.0,
            sample_count:  10,
        };
        let s = summarise(&[p]);
        assert_eq!(s.total_samples, 10);
        assert!((s.average - 75.0).abs() < 1e-9);
