        sqlx::query!(
            "UPDATE reporting.metric_definitions SET is_active = FALSE, updated_at = now() WHERE id = $1",
            id
        )
        .execute(&state.db)
        .await?;
    } else {
        sqlx::query!("DELETE FROM reporting.metric_definitions WHERE id = $1", id)
            .execute(&state.db)
