4	#[derive(Debug, thiserror::Error)]
5	pub enum AppError {
6	    #[error("Database error")]
7	    Database(#[from] sqlx::Error),
8	
9	    /// 401 — caller is not authenticated or token is invalid.
10	    #[error("Unauthorized: {0}")]
11	    Unauthorized(String),
12	
13	    /// 403 — caller is authenticated but lacks permission (e.g. reauth required).
14	    #[error("Forbidden: {0}")]
15	    Forbidden(String),
16	
17	    /// 400 — malformed request body or parameters.
18	    #[error("Bad request: {0}")]
19	    BadRequest(String),
20	
21	    /// 429 — account is locked due to too many failed attempts.
22	    #[error("Account locked until {0}")]
23	    AccountLocked(String),
24	
25	    /// 500 — unexpected server-side failure.
26	    #[error("Internal server error")]
27	    Internal(String),
28	}
29	
30	#[derive(Serialize)]
31	struct ErrorBody {
32	    error: String,
33	    code:  &'static str,
34	}
35	
36	impl AppError {
37	    fn error_code(&self) -> &'static str {
38	        match self {
39	            AppError::Database(_) | AppError::Internal(_) => "INTERNAL_ERROR",
40	            AppError::Unauthorized(_)                     => "UNAUTHORIZED",
41	            AppError::Forbidden(_)                        => "FORBIDDEN",
42	            AppError::BadRequest(_)                       => "BAD_REQUEST",
43	            AppError::AccountLocked(_)                    => "ACCOUNT_LOCKED",
44	        }
45	    }
46	}
47	
48	impl ResponseError for AppError {
49	    fn status_code(&self) -> StatusCode {
50	        match self {
51	            AppError::Database(_) | AppError::Internal(_) => StatusCode::INTERNAL_SERVER_ERROR,
52	            AppError::Unauthorized(_)                     => StatusCode::UNAUTHORIZED,
53	            AppError::Forbidden(_)                        => StatusCode::FORBIDDEN,
54	            AppError::BadRequest(_)                       => StatusCode::BAD_REQUEST,
55	            AppError::AccountLocked(_)                    => StatusCode::TOO_MANY_REQUESTS,
56	        }
57	    }
58	
59	    fn error_response(&self) -> HttpResponse {
60	        // Log server-side errors; surface nothing to the caller.
61	        if let AppError::Database(ref e) = self {
62	            tracing::error!("Database error: {:?}", e);
63	        }
64	        if let AppError::Internal(ref msg) = self {
65	            tracing::error!("Internal error: {}", msg);
66	        }
67	        HttpResponse::build(self.status_code()).json(ErrorBody {
68	            error: self.to_string(),
69	            code:  self.error_code(),
70	        })
71	    }
72	}
73	
74	impl From<argon2::password_hash::Error> for AppError {
75	    fn from(_err: argon2::password_hash::Error) -> Self {
76	        // Never leak hash internals to caller.
77	        AppError::Internal("Password processing error".to_string())
78	    }
79	}
