) -> Result<HttpResponse, AppError> {
    session.require(Permission::ReportingMetricsManage)?;
    let id = *path;

    let existing = sqlx::query_as!(
        super::models::MetricDefinitionRow,
        r#"
        SELECT id, metric_key, display_name, description,
