1	use actix_web::{web, App, HttpServer};
2	use dotenvy::dotenv;
3	use tracing_subscriber::{fmt, prelude::*, EnvFilter};
4	
5	mod auth;
6	mod config;
7	mod db;
8	mod dispatcher;
9	mod error;
10	mod notifications;
11	mod ops;
12	mod rbac;
13	mod reporting;
14	
15	/// Shared application state — cloned cheaply via `Arc` inside `web::Data`.
16	pub struct AppState {
17	    pub db:     sqlx::PgPool,
18	    pub config: config::Config,
19	}
20	
21	#[tokio::main]
22	async fn main() -> std::io::Result<()> {
23	    // Load .env (ignored if absent — production uses real env vars)
24	    dotenv().ok();
25	
26	    // Structured logging; set RUST_LOG=info or RUST_LOG=debug to control verbosity
27	    tracing_subscriber::registry()
28	        .with(fmt::layer())
29	        .with(EnvFilter::from_default_env())
30	        .init();
31	
32	    let cfg  = config::Config::from_env();
33	    let pool = db::create_pool(&cfg.database_url)
34	        .await
35	        .expect("Failed to connect to PostgreSQL");
36	
37	    let bind_addr = format!("{}:{}", cfg.server_host, cfg.server_port);
38	    tracing::info!("TransitOps backend listening on http://{}", bind_addr);
39	
40	    let state = web::Data::new(AppState { db: pool.clone(), config: cfg });
41	
42	    // Background event bus — polls every 5 s and fans out unprocessed events.
43	    // Must be spawned before the HTTP server so it starts processing immediately.
44	    tokio::spawn(notifications::bus::run_event_bus(pool.clone()));
45	
46	    // Background report scheduler — checks for due scheduled reports every 60 s.
47	    tokio::spawn(reporting::scheduler::run_report_scheduler(pool));
48	
49	    HttpServer::new(move || {
50	        App::new()
51	            .app_data(state.clone())
52	            // Reject payloads larger than 64 KiB for auth endpoints
53	            .app_data(web::JsonConfig::default().limit(65_536))
54	            .configure(auth::configure_routes)
55	            .configure(ops::configure_routes)
56	            .configure(dispatcher::configure_routes)
57	            .configure(notifications::configure_routes)
58	            .configure(reporting::configure_routes)
59	    })
60	    .bind(&bind_addr)?
61	    .run()
62	    .await
63	}
64	
