    results:      &[MetricResult],
    viewer_name:  &str,
    generated_at: DateTime<Utc>,
) -> Result<Vec<u8>, String> {
    let (doc, page1, layer1) =
        PdfDocument::new("TransitOps KPI Report", Mm(210.0), Mm(297.0), "Layer 1");

    let font = doc
        .add_builtin_font(BuiltinFont::HelveticaBold)
        .map_err(|e| e.to_string())?;
    let font_regular = doc
        .add_builtin_font(BuiltinFont::Helvetica)
        .map_err(|e| e.to_string())?;

    // Watermark text
    let watermark_text = format!(
        "{}  |  {}",
        viewer_name,
        generated_at.format("%Y-%m-%dT%H:%M:%SZ"),
    );

    // Page dimensions (A4)
    const PAGE_W: f64 = 210.0;
    const PAGE_H: f64 = 297.0;
    const MARGIN: f64 = 20.0;
    const LINE_H: f64 = 7.0;

    // Track current position across pages
    let mut current_layer = doc.get_page(page1).get_layer(layer1);
    let mut cursor_y: f64 = PAGE_H - MARGIN;

    // Helper: stamp the watermark on the current layer
    let stamp_watermark = |layer: &PdfLayerReference| {
        layer.set_fill_color(Color::Rgb(Rgb::new(0.85, 0.85, 0.85, None)));
        layer.use_text("", 1.0, Mm(0.0), Mm(0.0), &font); // init text state
        layer.set_text_matrix(TextMatrix::TranslateRotate(
            Mm(PAGE_W / 2.0 - 60.0),
            Mm(PAGE_H / 2.0 - 20.0),
            45.0,
        ));
        layer.write_text(watermark_text.clone(), &font_regular);
        // Reset colour to black for subsequent content
        layer.set_fill_color(Color::Rgb(Rgb::new(0.0, 0.0, 0.0, None)));
    };

    stamp_watermark(&current_layer);

    // Helper macro: add a new page, reset cursor, stamp watermark
    // (returns new layer reference and resets cursor_y)
    let add_page = |doc: &PdfDocumentReference, cursor_y: &mut f64| -> PdfLayerReference {
        let (new_page, new_layer) = doc.add_page(Mm(210.0), Mm(297.0), "Layer 1");
        let layer = doc.get_page(new_page).get_layer(new_layer);
        *cursor_y = PAGE_H - MARGIN;
        layer
    };

    // Ensure there is space for `lines` more lines on the current page.
    // If not, starts a new page.
    macro_rules! ensure_space {
        ($lines:expr) => {
            if cursor_y < MARGIN + ($lines as f64) * LINE_H {
                current_layer = add_page(&doc, &mut cursor_y);
                stamp_watermark(&current_layer);
            }
        };
    }

    // ---- Document title ----
    ensure_space!(3);
    current_layer.use_text(
        "TransitOps KPI Report",
        16.0,
        Mm(MARGIN),
        Mm(cursor_y),
        &font,
    );
    cursor_y -= LINE_H * 1.5;

    current_layer.use_text(
        format!(
            "Generated by {} at {}",
            viewer_name,
            generated_at.format("%Y-%m-%d %H:%M UTC")
        ),
        9.0,
        Mm(MARGIN),
        Mm(cursor_y),
        &font_regular,
    );
    cursor_y -= LINE_H * 2.0;

    // ---- One section per metric ----
    for result in results {
        ensure_space!(4);

        // Metric heading
        current_layer.use_text(
            format!("{} ({})", result.display_name, result.unit),
            12.0,
            Mm(MARGIN),
            Mm(cursor_y),
            &font,
        );
        cursor_y -= LINE_H;

        // Column headers
        ensure_space!(2);
        current_layer.use_text(
            format!("{:<28} {:>12} {:>14}", "Period Start", "Value", "Samples"),
            9.0,
            Mm(MARGIN),
            Mm(cursor_y),
            &font,
        );
        cursor_y -= LINE_H * 0.8;

        // Data rows
        for point in &result.series {
            ensure_space!(1);
            let line = format!(
                "{:<28} {:>11.2} {:>14}",
                point.period_start.format("%Y-%m-%d %H:%M"),
                point.value,
                point.sample_count,
            );
            current_layer.use_text(line, 9.0, Mm(MARGIN), Mm(cursor_y), &font_regular);
            cursor_y -= LINE_H;
        }

        // Summary block
        ensure_space!(4);
        cursor_y -= LINE_H * 0.5;
        current_layer.use_text(
            format!(
                "Summary — avg: {:.2}  min: {:.2}  max: {:.2}  total samples: {}",
                result.summary.average,
                result.summary.min,
                result.summary.max,
                result.summary.total_samples,
            ),
            9.0,
            Mm(MARGIN),
            Mm(cursor_y),
            &font_regular,
        );
        cursor_y -= LINE_H * 2.0;
    }

    // Serialise to bytes
    let mut raw: Vec<u8> = Vec::new();
    {
        let mut writer = BufWriter::new(&mut raw);
        doc.save(&mut writer).map_err(|e| e.to_string())?;
    }
    Ok(raw)
}", "new_string": "pub fn to_pdf(
    results:      &[MetricResult],
    viewer_name:  &str,
    generated_at: DateTime<Utc>,
) -> Result<Vec<u8>, String> {
    let (doc, page1, layer1) =
        PdfDocument::new("TransitOps KPI Report", Mm(210.0), Mm(297.0), "Layer 1");

    let font = doc
        .add_builtin_font(BuiltinFont::HelveticaBold)
        .map_err(|e| e.to_string())?;
    let font_regular = doc
        .add_builtin_font(BuiltinFont::Helvetica)
        .map_err(|e| e.to_string())?;

    // Watermark text — "<viewer>  |  <timestamp>"
    let watermark_text = format!(
        "{}  |  {}",
        viewer_name,
        generated_at.format("%Y-%m-%dT%H:%M:%SZ"),
    );

    // Page dimensions (A4 in mm)
    const PAGE_W: f64 = 210.0;
    const PAGE_H: f64 = 297.0;
    const MARGIN: f64 = 20.0;
    const LINE_H: f64 = 7.0;

    // ---- helper: stamp diagonal watermark ----
    // Uses begin/set_text_matrix/write_text/end so rotation is applied correctly.
    let stamp_watermark = |layer: &PdfLayerReference| {
        layer.set_fill_color(Color::Rgb(Rgb::new(0.85, 0.85, 0.85, None)));
        layer.begin_text_section();
        layer.set_font(&font_regular, 14.0);
        layer.set_text_matrix(TextMatrix::TranslateRotate(
            Mm(PAGE_W / 2.0 - 60.0),
            Mm(PAGE_H / 2.0 - 20.0),
            45.0,
        ));
        layer.write_text(watermark_text.clone(), &font_regular);
        layer.end_text_section();
        layer.set_fill_color(Color::Rgb(Rgb::new(0.0, 0.0, 0.0, None)));
    };

    // Track current page layer and Y cursor
    let mut current_layer = doc.get_page(page1).get_layer(layer1);
    let mut cursor_y: f64 = PAGE_H - MARGIN;
    stamp_watermark(&current_layer);

    // Macro: ensure N lines of space; breaks to a new page if not enough room.
    macro_rules! ensure_space {
        ($lines:expr) => {
            if cursor_y < MARGIN + ($lines as f64) * LINE_H {
                let (new_page, new_layer) = doc.add_page(Mm(PAGE_W), Mm(PAGE_H), "Layer 1");
                current_layer = doc.get_page(new_page).get_layer(new_layer);
                cursor_y = PAGE_H - MARGIN;
                stamp_watermark(&current_layer);
            }
        };
    }

    // ---- Document title ----
    ensure_space!(3);
