        "#,
        body.idempotency_key,
        body.trip_id,
        body.route_id,
        body.amount,
        currency,
        body.payment_method,
        session.user_id,
        metadata,
    )
    .fetch_one(&state.db)
    .await?;

    Ok(HttpResponse::Created().json(TransactionResponse::from(row)))
}

