        let entry_type = match get(type_col).to_lowercase().as_str() {
            "debit"  => EntryType::Debit,
            "credit" => EntryType::Credit,
            other    => {
                errors.push(format!(
                    "Line {}: invalid 'type' '{}' — expected 'debit' or 'credit'",
                    line_no, other
                ));
                continue;
            }
        };

