    state:   web::Data<AppState>,
    session: AuthSession,
) -> Result<HttpResponse, AppError> {
    session.require(Permission::PaymentsStatementsRead)?;

    #[derive(sqlx::FromRow, serde::Serialize)]
    struct StmtRow {
        id:              Uuid,
        filename:        String,
        file_hash:       String,
        source:          String,
        import_date:     chrono::NaiveDate,
        status:          String,
        total_records:   i32,
        error_count:     i32,
        imported_by:     Uuid,
        created_at:      chrono::DateTime<Utc>,
