    let rows = sqlx::query_as!(
        StmtRow,
        r#"
        SELECT id, filename, file_hash, source, import_date, status,
               total_records, error_count, imported_by, created_at
        FROM payments.statement_imports
        ORDER BY import_date DESC, created_at DESC
        LIMIT 100
