11	///
12	/// Rules enforced by `validate_and_parse`:
13	///   1. Content must be valid UTF-8.
14	///   2. First non-blank row must contain exactly the headers:
15	///      `date`, `ref`, `amount`, `type`, `description`
16	///      (case-insensitive; any column order; `description` is optional).
17	///   3. Required columns: `date`, `ref`, `amount`, `type`.
18	///   4. `date` must parse as `YYYY-MM-DD`.
19	///   5. `amount` must be a non-negative decimal (commas stripped).
20	///   6. `type` must be `debit` or `credit` (case-insensitive).
21	///   7. `ref` must be non-empty.
22	///
23	/// A parse result is returned even when errors exist; the caller decides
24	/// whether to abort or continue with warnings.
25	use chrono::NaiveDate;
26	use sha2::{Digest, Sha256};
27	
28	use super::models::{EntryType, ParseResult, StatementRecord};
29	
30	// ============================================================
31	// SHA-256 fingerprint
32	// ============================================================
33	
34	/// Compute the SHA-256 fingerprint of raw file bytes, hex-encoded.
35	pub fn fingerprint(data: &[u8]) -> String {
36	    let mut h = Sha256::new();
37	    h.update(data);
38	    hex::encode(h.finalize())
39	}
40	
41	/// Verify that the SHA-256 of `data` matches `expected_hex`.
42	/// Returns `true` on match, `false` on mismatch.
43	pub fn verify_fingerprint(data: &[u8], expected_hex: &str) -> bool {
44	    fingerprint(data) == expected_hex.to_lowercase()
45	}
46	
47	// ============================================================
48	// Required CSV column set
49	// ============================================================
50	
51	const REQUIRED_HEADERS: &[&str] = &["date", "ref", "amount", "type"];
52	const OPTIONAL_HEADER:   &str    = "description";
53	
54	// ============================================================
55	// Strict CSV parser / validator
56	// ============================================================
57	
58	/// Validate file format and parse records from raw CSV bytes.
59	///
60	/// Always returns a `ParseResult`; check `is_valid` before using `records`
61	/// for production reconciliation.
62	pub fn validate_and_parse(content: &[u8]) -> ParseResult {
63	    let mut errors:  Vec<String> = Vec::new();
64	    let mut records: Vec<StatementRecord> = Vec::new();
65	
66	    // ---- UTF-8 check ----
67	    let text = match std::str::from_utf8(content) {
68	        Ok(s)  => s,
69	        Err(_) => {
70	            return ParseResult {
71	                is_valid:    false,
72	                errors:      vec!["File is not valid UTF-8".to_string()],
73	                records:     vec![],
74	                fingerprint: fingerprint(content),
75	            };
76	        }
77	    };
78	
79	    // ---- CSV reader ----
80	    let mut reader = csv::ReaderBuilder::new()
81	        .has_headers(true)
82	        .flexible(false)          // require consistent column count
83	        .trim(csv::Trim::All)
84	        .from_reader(text.as_bytes());
85	
86	    // ---- Header validation ----
87	    let headers = match reader.headers() {
88	        Ok(h)  => h.clone(),
89	        Err(e) => {
90	            return ParseResult {
91	                is_valid:    false,
92	                errors:      vec![format!("Cannot read CSV headers: {}", e)],
93	                records:     vec![],
94	                fingerprint: fingerprint(content),
95	            };
96	        }
97	    };
98	
99	    let norm_headers: Vec<String> = headers.iter().map(|h| h.to_lowercase()).collect();
100	
101	    for &required in REQUIRED_HEADERS {
102	        if !norm_headers.contains(&required.to_string()) {
103	            errors.push(format!("Missing required column: '{}'", required));
104	        }
105	    }
106	
107	    let col = |name: &str| -> Option<usize> {
108	        norm_headers.iter().position(|h| h == name)
109	    };
110	
111	    let Some(date_col)   = col("date")   else { /* already in errors */ return ParseResult { is_valid: false, errors, records, fingerprint: fingerprint(content) }; };
112	    let Some(ref_col)    = col("ref")    else { return ParseResult { is_valid: false, errors, records, fingerprint: fingerprint(content) }; };
113	    let Some(amount_col) = col("amount") else { return ParseResult { is_valid: false, errors, records, fingerprint: fingerprint(content) }; };
114	    let Some(type_col)   = col("type")   else { return ParseResult { is_valid: false, errors, records, fingerprint: fingerprint(content) }; };
115	    let desc_col = col(OPTIONAL_HEADER);
116	
117	    if !errors.is_empty() {
118	        return ParseResult {
119	            is_valid: false,
120	            errors,
121	            records,
122	            fingerprint: fingerprint(content),
123	        };
124	    }
125	
126	    // ---- Row validation and parsing ----
127	    for (row_idx, result) in reader.records().enumerate() {
128	        let line_no = row_idx + 2; // 1-based, row 1 is headers
129	
130	        let record = match result {
131	            Ok(r)  => r,
132	            Err(e) => {
133	                errors.push(format!("Line {}: CSV parse error — {}", line_no, e));
134	                continue;
135	            }
136	        };
137	
138	        let get = |idx: usize| record.get(idx).unwrap_or("").trim().to_string();
139	
140	        // --- ref ---
141	        let reference = get(ref_col);
142	        if reference.is_empty() {
143	            errors.push(format!("Line {}: 'ref' must not be empty", line_no));
144	            continue;
145	        }
146	
147	        // --- date ---
148	        let date_str = get(date_col);
149	        let date = match NaiveDate::parse_from_str(&date_str, "%Y-%m-%d") {
150	            Ok(d)  => d,
151	            Err(_) => {
152	                errors.push(format!(
153	                    "Line {}: invalid 'date' '{}' — expected YYYY-MM-DD",
154	                    line_no, date_str
155	                ));
156	                continue;
157	            }
158	        };
159	
160	        // --- amount ---
161	        let amount_str = get(amount_col).replace(',', "");
162	        let amount: f64 = match amount_str.parse() {
163	            Ok(a)  => a,
164	            Err(_) => {
165	                errors.push(format!(
166	                    "Line {}: invalid 'amount' '{}' — expected a decimal number",
167	                    line_no, amount_str
168	                ));
169	                continue;
170	            }
171	        };
172	        if amount < 0.0 {
173	            errors.push(format!(
174	                "Line {}: 'amount' must be non-negative, got {}",
175	                line_no, amount
176	            ));
177	            continue;
178	        }
179	
180	        // --- type ---
181	        let entry_type = match get(type_col).to_lowercase().as_str() {
182	            "debit"  => EntryType::Debit,
183	            "credit" => EntryType::Credit,
184	            other    => {
185	                errors.push(format!(
186	                    "Line {}: invalid 'type' '{}' — expected 'debit' or 'credit'",
187	                    line_no, other
188	                ));
189	                continue;
190	            }
191	        };
192	
193	        records.push(StatementRecord {
194	            reference,
195	            amount,
196	            entry_type,
197	            date,
198	            description: desc_col.map(|i| get(i)).filter(|s| !s.is_empty()),
199	        });
200	    }
201	
202	    ParseResult {
203	        is_valid:    errors.is_empty(),
204	        errors,
205	        records,
206	        fingerprint: fingerprint(content),
207	    }
208	}
