1	/// Payment result file import — parsing and matching.
2	///
3	/// Supports two file formats:
4	///   - CSV: header row `ref,amount,date,description` (case-insensitive)
5	///   - JSON: array of objects with the same field names
6	///
7	/// Flow:
8	///   1. Caller uploads file via `POST /payments/imports` with base64 content.
9	///   2. System computes SHA-256 to detect duplicates.
10	///   3. A `statement_imports` row is created (status = 'pending').
11	///   4. `POST /payments/imports/{id}/process` triggers `process_import_file`.
12	///   5. Each line is parsed, stored in `statement_import_lines`, and matched
13	///      against `payments.transactions` by `idempotency_key` or amount+date.
14	use chrono::NaiveDate;
15	use serde::Deserialize;
16	use sha2::{Digest, Sha256};
17	use sqlx::PgPool;
18	use uuid::Uuid;
19	
20	// ============================================================
21	// Parsed import line
22	// ============================================================
23	
24	#[derive(Debug, Clone)]
25	pub struct ImportLine {
26	    pub transaction_ref: Option<String>,
27	    pub amount:          f64,
28	    pub transaction_date: NaiveDate,
29	    pub description:     Option<String>,
30	}
31	
32	// ============================================================
33	// SHA-256 helper
34	// ============================================================
35	
36	pub fn sha256_hex(data: &[u8]) -> String {
37	    let mut h = Sha256::new();
38	    h.update(data);
39	    hex::encode(h.finalize())
40	}
41	
42	// ============================================================
43	// CSV parser
44	// ============================================================
45	
46	/// Expected CSV headers (case-insensitive):
47	///   ref, amount, date, description
48	///
49	/// `ref` and `description` are optional — missing fields become `None`.
50	/// `amount` and `date` are required; rows with unparseable values are skipped.
51	pub fn parse_csv(content: &[u8]) -> Result<Vec<ImportLine>, String> {
52	    let mut reader = csv::ReaderBuilder::new()
53	        .has_headers(true)
54	        .flexible(true)
55	        .from_reader(content);
56	
57	    let headers = reader.headers().map_err(|e| e.to_string())?.clone();
58	    let col = |name: &str| -> Option<usize> {
59	        headers.iter().position(|h| h.to_lowercase() == name)
60	    };
61	
62	    let ref_col   = col("ref");
63	    let amt_col   = col("amount").ok_or("CSV missing 'amount' column")?;
64	    let date_col  = col("date").ok_or("CSV missing 'date' column")?;
65	    let desc_col  = col("description");
66	
67	    let mut lines = Vec::new();
68	
69	    for (row_idx, result) in reader.records().enumerate() {
70	        let record = match result {
71	            Ok(r)  => r,
72	            Err(e) => {
73	                tracing::warn!(row = row_idx + 2, error = %e, "CSV row parse error, skipping");
74	                continue;
75	            }
76	        };
77	
78	        let get = |idx: usize| record.get(idx).unwrap_or("").trim().to_string();
79	
80	        let amount = match get(amt_col).replace(',', "").parse::<f64>() {
81	            Ok(a)  => a,
82	            Err(_) => {
83	                tracing::warn!(row = row_idx + 2, "Invalid amount, skipping row");
84	                continue;
85	            }
86	        };
87	
88	        let transaction_date = match NaiveDate::parse_from_str(&get(date_col), "%Y-%m-%d")
89	            .or_else(|_| NaiveDate::parse_from_str(&get(date_col), "%d/%m/%Y"))
90	            .or_else(|_| NaiveDate::parse_from_str(&get(date_col), "%m/%d/%Y"))
91	        {
92	            Ok(d)  => d,
93	            Err(_) => {
94	                tracing::warn!(row = row_idx + 2, "Invalid date, skipping row");
95	                continue;
96	            }
97	        };
98	
99	        lines.push(ImportLine {
100	            transaction_ref:  ref_col.map(|i| get(i)).filter(|s| !s.is_empty()),
101	            amount,
102	            transaction_date,
103	            description:       desc_col.map(|i| get(i)).filter(|s| !s.is_empty()),
104	        });
105	    }
106	
107	    Ok(lines)
108	}
109	
110	// ============================================================
111	// JSON parser
112	// ============================================================
113	
114	#[derive(Debug, Deserialize)]
115	struct JsonImportLine {
116	    #[serde(rename = "ref", alias = "reference", alias = "transaction_ref")]
117	    transaction_ref:  Option<String>,
118	    amount:           f64,
119	    #[serde(alias = "transaction_date", alias = "date")]
120	    date:             String,
121	    description:      Option<String>,
122	}
123	
124	/// Expected JSON format:
125	/// ```json
126	/// [
127	///   { "ref": "TXN001", "amount": 100.00, "date": "2025-01-15", "description": "Bus fare" },
128	///   ...
129	/// ]
130	/// ```
131	pub fn parse_json(content: &[u8]) -> Result<Vec<ImportLine>, String> {
132	    let raw: Vec<JsonImportLine> =
133	        serde_json::from_slice(content).map_err(|e| e.to_string())?;
134	
135	    let mut lines = Vec::new();
136	    for (i, item) in raw.into_iter().enumerate() {
137	        let transaction_date = NaiveDate::parse_from_str(&item.date, "%Y-%m-%d")
138	            .or_else(|_| NaiveDate::parse_from_str(&item.date, "%d/%m/%Y"))
139	            .map_err(|_| format!("row {}: invalid date '{}'", i + 1, item.date))?;
140	
141	        lines.push(ImportLine {
142	            transaction_ref:  item.transaction_ref,
143	            amount:           item.amount,
144	            transaction_date,
145	            description:      item.description,
146	        });
147	    }
148	    Ok(lines)
149	}
150	
151	// ============================================================
152	// DB processing
153	// ============================================================
154	
155	/// Parse a previously stored import file and populate `statement_import_lines`.
156	///
157	/// For each line:
158	///   - Inserts a `statement_import_lines` row.
159	///   - Attempts to match against `payments.transactions` by idempotency_key
160	///     (using `transaction_ref`) and, as a fallback, by amount on the same date.
161	///
162	/// Returns `(total, matched)` counts.  Updates the import's status and counters.
163	pub async fn process_import_file(
164	    pool:      &PgPool,
165	    import_id: Uuid,
166	    format:    &str,
167	    content:   &[u8],
168	) -> Result<(i32, i32), sqlx::Error> {
169	    let lines = match format {
170	        "json" => parse_json(content).unwrap_or_default(),
171	        _      => parse_csv(content).unwrap_or_default(),
172	    };
173	
174	    let total = lines.len() as i32;
175	    let mut matched = 0i32;
176	    let mut errors  = 0i32;
177	
178	    for (line_no, line) in lines.iter().enumerate() {
179	        let line_number = (line_no + 1) as i32;
180	
181	        // Attempt to match by transaction_ref → idempotency_key
182	        let matched_id: Option<Uuid> = if let Some(ref txn_ref) = line.transaction_ref {
183	            sqlx::query_scalar!(
184	                "SELECT id FROM payments.transactions WHERE idempotency_key = $1 LIMIT 1",
185	                txn_ref,
186	            )
187	            .fetch_optional(pool)
188	            .await
189	            .ok()
190	            .flatten()
191	        } else {
192	            None
193	        };
194	
195	        // Fallback: match by amount + date range (same calendar day)
196	        let matched_id = if matched_id.is_none() {
197	            let day_start = line.transaction_date.and_hms_opt(0, 0, 0)
198	                .map(|dt| chrono::DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc));
199	            let day_end   = line.transaction_date.and_hms_opt(23, 59, 59)
200	                .map(|dt| chrono::DateTime::<Utc>::from_naive_utc_and_offset(dt, Utc));
201	
202	            if let (Some(start), Some(end)) = (day_start, day_end) {
203	                sqlx::query_scalar!(
204	                    r#"
205	                    SELECT id FROM payments.transactions
206	                    WHERE amount    = $1
207	                      AND created_at BETWEEN $2 AND $3
208	                      AND status    = 'completed'
209	                    LIMIT 1
210	                    "#,
211	                    line.amount as f64,
212	                    start,
213	                    end,
214	                )
215	                .fetch_optional(pool)
216	                .await
217	                .ok()
218	                .flatten()
219	            } else {
220	                None
221	            }
222	        } else {
223	            matched_id
224	        };
225	
226	        let match_status = if matched_id.is_some() {
227	            matched += 1;
228	            "matched"
229	        } else {
230	            "unmatched"
231	        };
232	
233	        let result = sqlx::query!(
234	            r#"
235	            INSERT INTO payments.statement_import_lines
236	                (import_id, line_number, transaction_ref, amount,
237	                 transaction_date, description, matched_transaction_id, match_status)
238	            VALUES ($1, $2, $3, $4, $5, $6, $7, $8)
239	            ON CONFLICT (import_id, line_number) DO NOTHING
240	            "#,
241	            import_id,
242	            line_number,
243	            line.transaction_ref.as_deref(),
244	            line.amount,
245	            line.transaction_date,
246	            line.description.as_deref(),
247	            matched_id,
248	            match_status,
249	        )
250	        .execute(pool)
251	        .await;
252	
253	        if let Err(e) = result {
254	            tracing::warn!(line_number, error = %e, "Failed to insert import line");
255	            errors += 1;
256	        }
257	    }
258	
259	    // Update import record
260	    sqlx::query!(
261	        r#"
262	        UPDATE payments.statement_imports
263	        SET status            = CASE WHEN $3 = 0 THEN 'completed' ELSE 'failed' END,
264	            total_records     = $2,
265	            processed_records = $2 - $3,
266	            error_count       = $3,
267	            updated_at        = now()
268	        WHERE id = $1
269	        "#,
270	        import_id,
271	        total,
272	        errors,
273	    )
274	    .execute(pool)
275	    .await?;
276	
277	    Ok((total, matched))
278	}
