1	use actix_web::{web, App, HttpServer};
2	use dotenvy::dotenv;
3	use tracing_subscriber::{fmt, prelude::*, EnvFilter};
4	
5	mod alerting;
6	mod auth;
7	mod config;
8	mod db;
9	mod dispatcher;
10	mod error;
11	mod notifications;
12	mod ops;
13	mod payments;
14	mod rbac;
15	mod reconciliation;
16	mod reporting;
17	
18	/// Shared application state — cloned cheaply via `Arc` inside `web::Data`.
19	pub struct AppState {
20	    pub db:     sqlx::PgPool,
21	    pub config: config::Config,
22	}
23	
24	#[tokio::main]
25	async fn main() -> std::io::Result<()> {
26	    // Load .env (ignored if absent — production uses real env vars)
27	    dotenv().ok();
28	
29	    // Structured logging; set RUST_LOG=info or RUST_LOG=debug to control verbosity
30	    tracing_subscriber::registry()
31	        .with(fmt::layer())
32	        .with(EnvFilter::from_default_env())
33	        .init();
34	
35	    let cfg  = config::Config::from_env();
36	    let pool = db::create_pool(&cfg.database_url)
37	        .await
38	        .expect("Failed to connect to PostgreSQL");
39	
40	    let bind_addr = format!("{}:{}", cfg.server_host, cfg.server_port);
41	    tracing::info!("TransitOps backend listening on http://{}", bind_addr);
42	
43	    let state = web::Data::new(AppState { db: pool.clone(), config: cfg });
44	
45	    // Background event bus — polls every 5 s and fans out unprocessed events.
46	    // Must be spawned before the HTTP server so it starts processing immediately.
47	    tokio::spawn(notifications::bus::run_event_bus(pool.clone()));
48	
49	    // Background report scheduler — checks for due scheduled reports every 60 s.
50	    tokio::spawn(reporting::scheduler::run_report_scheduler(pool.clone()));
51	
52	    // Background payment compensation sweeps — run every 15 minutes.
53	    // Handles stuck transactions, pending refunds, and unprocessed callbacks.
54	    tokio::spawn(payments::compensation::run_compensation_scheduler(pool.clone()));
55	
56	    // Background KPI anomaly checker — evaluates metric snapshots every 30 minutes
57	    // and creates alerting.alerts rows when deviation exceeds the configured threshold.
58	    tokio::spawn(alerting::detector::run_kpi_anomaly_scheduler(pool));
59	
60	    HttpServer::new(move || {
61	        App::new()
62	            .app_data(state.clone())
63	            // Reject payloads larger than 64 KiB for auth endpoints
64	            .app_data(web::JsonConfig::default().limit(65_536))
65	            .configure(auth::configure_routes)
66	            .configure(ops::configure_routes)
67	            .configure(dispatcher::configure_routes)
68	            .configure(notifications::configure_routes)
69	            .configure(payments::configure_routes)
70	            .configure(reconciliation::configure_routes)
71	            .configure(reporting::configure_routes)
72	            .configure(alerting::configure_routes)
73	    })
74	    .bind(&bind_addr)?
75	    .run()
76	    .await
77	}
