/// POST /ops/configs/{template_id}/versions/{version_id}/publish
pub async fn publish_version(
    state:   web::Data<AppState>,
    session: AuthSession,
    path:    web::Path<(Uuid, Uuid)>,
) -> Result<HttpResponse, AppError> {
    session.require(Permission::OpsConfigPublish)?;
    let (template_id, version_id) = path.into_inner();
    let mut tx = state.db.begin().await?;
    // Archive current published version (if any)
    sqlx::query("UPDATE ops.config_versions SET status = 'archived', updated_at = now() WHERE template_id = $1 AND status = 'published'")
        .bind(template_id).execute(&mut *tx).await?;
    // Publish the target version
    let affected = sqlx::query("UPDATE ops.config_versions SET status = 'published', published_at = now(), updated_at = now() WHERE id = $1 AND template_id = $2 AND status IN ('draft', 'scheduled')")
        .bind(version_id).bind(template_id).execute(&mut *tx).await?.rows_affected();
    if affected == 0 {
        tx.rollback().await?;
        return Err(AppError::BadRequest("Version not found or is not in draft/scheduled status".to_string()));
    }
    tx.commit().await?;
    Ok(HttpResponse::Ok().json(OkResponse { message: "Version published" }))
}

/// POST /ops/configs/{template_id}/versions/{version_id}/unpublish
pub async fn unpublish_version(
    state:   web::Data<AppState>,
    session: AuthSession,
    path:    web::Path<(Uuid, Uuid)>,
) -> Result<HttpResponse, AppError> {
    session.require(Permission::OpsConfigPublish)?;
    let (template_id, version_id) = path.into_inner();
    let affected = sqlx::query("UPDATE ops.config_versions SET status = 'draft', published_at = NULL, updated_at = now() WHERE id = $1 AND template_id = $2 AND status = 'published'")
        .bind(version_id).bind(template_id).execute(&state.db).await?.rows_affected();
    if affected == 0 {
        return Err(AppError::BadRequest("Version not found or is not currently published".to_string()));
    }
    Ok(HttpResponse::Ok().json(OkResponse { message: "Version unpublished" }))
}
```

