1	use actix_web::{web, App, HttpServer};
2	use dotenvy::dotenv;
3	use tracing_subscriber::{fmt, prelude::*, EnvFilter};
4	
5	mod alerting;
6	mod audit;
7	mod auth;
8	mod config;
9	mod db;
10	mod dispatcher;
11	mod error;
12	mod notifications;
13	mod ops;
14	mod payments;
15	mod rbac;
16	mod reconciliation;
17	mod reporting;
18	
19	/// Shared application state — cloned cheaply via `Arc` inside `web::Data`.
20	pub struct AppState {
21	    pub db:     sqlx::PgPool,
22	    pub config: config::Config,
23	}
24	
25	#[tokio::main]
26	async fn main() -> std::io::Result<()> {
27	    // Load .env (ignored if absent — production uses real env vars)
28	    dotenv().ok();
29	
30	    // Structured logging; set RUST_LOG=info or RUST_LOG=debug to control verbosity
