            sqlx::query(
                "INSERT INTO notifications.deliveries (event_id, user_id, status) \
                 VALUES ($1, $2, 'queued') \
                 ON CONFLICT (event_id, user_id) DO NOTHING",
            )
            .bind(event.id)
            .bind(user_id)
            .execute(pool)
            .await?;
