pub fn notifications_reducer(
    mut state: NotificationsState,
    action:    NotificationsAction,
) -> NotificationsState {
    match action {
        NotificationsAction::SetInbox(cache) => { state.inbox = cache; }
        NotificationsAction::AppendInbox(items) => {
            state.inbox.items.extend(items);
            state.inbox.offset += state.inbox.limit;
        }
        NotificationsAction::MarkRead(id) => {
            if let Some(item) = state.inbox.items.iter_mut().find(|n| n.id == id) {
                item.status = "read".to_string();
                item.read_at = Some(chrono::Utc::now());
            }
            state.unread_count = state.unread_count.saturating_sub(1);
        }
        NotificationsAction::SetCounts { unread, queued } => {
            state.unread_count = unread;
            state.queued_count = queued;
        }
        // ...
    }
    state
}
