## API integration layer

### `src/api/client.rs`

```rust
/// Thin wrapper around gloo-net; all requests flow through here.
pub struct ApiClient {
    base_url: String,
}

impl ApiClient {
    /// Execute a request, attaching the auth token from context.
    /// Handles 401 → clear token + redirect to /login.
    pub async fn request<T: DeserializeOwned>(
        &self,
        method:  Method,
        path:    &str,
        body:    Option<&impl Serialize>,
        token:   Option<&str>,
    ) -> Result<T, ApiError> {
        let url = format!("{}{}", self.base_url, path);

        let mut builder = Request::new(&url).method(method);
        if let Some(t) = token {
            builder = builder.header("Authorization", &format!("Bearer {}", t));
        }
        if let Some(b) = body {
            builder = builder
                .header("Content-Type", "application/json")
                .body(serde_json::to_string(b)?)?;
        }

        let resp = builder.send().await.map_err(ApiError::Network)?;

        match resp.status() {
            200..=299 => Ok(resp.json::<T>().await.map_err(ApiError::Parse)?),
            401       => Err(ApiError::Unauthorized),
            403       => Err(ApiError::Forbidden),
            422       => Err(ApiError::Validation(resp.json().await.unwrap_or_default())),
            status    => Err(ApiError::Server(status, resp.text().await.unwrap_or_default())),
        }
    }
}
```

