```rust
/// Write a serializable value to localStorage under a namespaced key.
pub fn cache_write<T: Serialize>(key: &str, value: &T) {
    let _ = LocalStorage::set(format!("transitops.{}", key), value);
}

/// Read back; returns None if absent or deserialization fails.
pub fn cache_read<T: DeserializeOwned>(key: &str) -> Option<T> {
    LocalStorage::get(format!("transitops.{}", key)).ok()
}
