```rust
/// Mounts once; subscribes to browser online/offline events and
/// drives NetworkState + triggers SyncQueueWorker.
#[function_component(NetworkWatcher)]
pub fn network_watcher() -> Html {
    let app_dispatch = use_context::<AppDispatch>().unwrap();

    use_effect_with((), move |_| {
        let window = web_sys::window().unwrap();
        let navigator = window.navigator();

        // Set initial state
        app_dispatch.emit(AppAction::SetOnline(navigator.on_line()));

        // online event
        let d = app_dispatch.clone();
        let on_online = Closure::<dyn Fn()>::new(move || {
            d.emit(AppAction::SetOnline(true));
        });
        window.add_event_listener_with_callback("online", on_online.as_ref().unchecked_ref()).unwrap();

        // offline event
        let d = app_dispatch.clone();
        let on_offline = Closure::<dyn Fn()>::new(move || {
            d.emit(AppAction::SetOnline(false));
        });
        window.add_event_listener_with_callback("offline", on_offline.as_ref().unchecked_ref()).unwrap();

        move || { /* cleanup */ }
    });

    html! {}
}
```

### `src/components/layout/sync_queue_worker.rs`

```rust
/// When `NetworkState.online` flips to true, drains the SyncQueue
/// and replays each mutation in order.
#[function_component(SyncQueueWorker)]
pub fn sync_queue_worker() -> Html {
    let network  = use_context::<NetworkStateContext>().unwrap();
    let auth     = use_auth();
    let dispatch = use_context::<AppDispatch>().unwrap();

    use_effect_with(network.online, move |&online| {
        if online {
            let token = auth.token.clone();
            wasm_bindgen_futures::spawn_local(async move {
                let mutations = SyncQueue::drain();
                for m in mutations {
                    if let Err(e) = replay_mutation(&m, token.as_deref()).await {
                        tracing::warn!("Replay failed, re-enqueuing: {:?}", e);
                        SyncQueue::enqueue(m);
                    }
                }
                dispatch.emit(AppAction::SyncQueueChanged(SyncQueue::len()));
            });
        }
    });

    html! {}
}
```

