## Dispatch panel — polling pattern

The Dispatch view needs live trip updates without a WebSocket. It uses a 5-second poll via `use_poll`:

```rust
#[function_component(DispatchPanelView)]
pub fn dispatch_view() -> Html {
    let ctx      = use_context::<DispatchContext>().unwrap();
    let auth     = use_auth();

    // Fetch immediately on mount, then every 5s
    let fetch = {
        let ctx  = ctx.clone();
        let auth = auth.clone();
        Callback::from(move |_| {
            let ctx  = ctx.clone();
            let auth = auth.clone();
            wasm_bindgen_futures::spawn_local(async move {
                if let Ok(trips) = api::dispatch::list_trips(&auth.token()).await {
                    ctx.dispatch(DispatchAction::SetTrips(trips));
                }
            });
        })
    };

    use_poll(5_000, fetch);   // returns cleanup handle

    html! {
        <>
            <PollingIndicator />
            <TripFilterBar />
            <TripList trips={ctx.state.trips.items.clone()} />
        </>
    }
}
