37	        FROM reporting.scheduled_reports
38	        WHERE is_active = TRUE
39	          AND next_run_at <= now()
40	        FOR UPDATE SKIP LOCKED
41	        "#,
42	    )
43	    .fetch_all(pool)
44	    .await?;
45	
46	    for report in due {
