59	    _user_id: Uuid,
60	) {
61	    let now       = Utc::now();
62	    let date_to   = now;
63	    let date_from = date_to - chrono::Duration::days(report.date_range_days as i64);
64	
65	    let mut results = Vec::new();
66	    let mut failed  = false;
67	
68	    for &metric_id in &report.metric_ids {
69	        let def = match sqlx::query_as!(
70	            super::models::MetricDefinitionRow,
71	            r#"
72	            SELECT id, metric_key, display_name, description,
73	                   formula_type, dimension_keys, config,
74	                   is_builtin, is_active, created_at, updated_at
75	            FROM reporting.metric_definitions
76	            WHERE id = $1 AND is_active = TRUE
77	            "#,
78	            metric_id,
79	        )
80	        .fetch_optional(pool)
81	        .await
82	        {
83	            Ok(Some(d)) => d,
84	            Ok(None) => {
85	                tracing::warn!(metric_id = %metric_id, "metric not found during triggered run");
86	                continue;
87	            }
88	            Err(e) => {
89	                tracing::error!(metric_id = %metric_id, error = %e, "metric load failed");
90	                failed = true;
91	                break;
92	            }
93	        };
94	
95	        let query = MetricQuery {
96	            metric_id,
