138	    let date_to = now;
139	    let date_from = date_to - Duration::days(report.date_range_days as i64);
140	
141	    // Create a run record in 'running' state
142	    let run_id: Uuid = match sqlx::query_scalar!(
143	        r#"
144	        INSERT INTO reporting.report_runs
145	            (scheduled_id, metric_ids, route_id, depot_id,
146	             date_from, date_to, granularity, output_format, status, started_at)
147	        VALUES ($1, $2, $3, $4, $5, $6, $7, $8, 'running', now())
148	        RETURNING id
149	        "#,
150	        report.id,
151	        &report.metric_ids,
152	        report.route_id,
153	        report.depot_id,
154	        date_from,
155	        date_to,
156	        report.granularity,
157	        report.output_format,
158	    )
159	    .fetch_one(pool)
160	    .await
161	    {
162	        Ok(id) => id,
163	        Err(e) => {
164	            tracing::error!(scheduled_id = %report.id, error = %e, "failed to insert run record");
165	            return;
166	        }
167	    };
168	
169	    // Compute each metric
170	    let mut results = Vec::new();
171	    let mut failed  = false;
172	
173	    for &metric_id in &report.metric_ids {
174	        let def = match sqlx::query_as!(
175	            super::models::MetricDefinitionRow,
176	            r#"
177	            SELECT id, metric_key, display_name, description,
178	                   formula_type, dimension_keys, config,
179	                   is_builtin, is_active, created_at, updated_at
180	            FROM reporting.metric_definitions
181	            WHERE id = $1 AND is_active = TRUE
182	            "#,
183	            metric_id,
184	        )
185	        .fetch_optional(pool)
186	        .await
187	        {
188	            Ok(Some(d)) => d,
189	            Ok(None) => {
190	                tracing::warn!(metric_id = %metric_id, "metric not found or inactive during scheduled run");
191	                continue;
192	            }
193	            Err(e) => {
194	                tracing::error!(metric_id = %metric_id, error = %e, "failed to load metric def");
195	                failed = true;
196	                break;
197	            }
198	        };
199	
200	        let query = MetricQuery {
201	            metric_id,
202	            date_from,
203	            date_to,
204	            granularity: report.granularity.clone(),
205	            route_id:    report.route_id,
206	            depot_id:    report.depot_id,
207	        };
208	
209	        match compute_metric(pool, &def, &query).await {
210	            Ok(r)  => results.push(r),
211	            Err(e) => {
212	                tracing::error!(
213	                    metric_id = %metric_id,
214	                    scheduled_id = %report.id,
215	                    error = %e,
216	                    "metric computation failed"
217	                );
218	                failed = true;
219	                break;
220	            }
221	        }
222	    }
223	
224	    // Persist results and advance schedule
225	    let result_json = serde_json::to_value(&results).unwrap_or(serde_json::Value::Null);
226	
227	    if failed {
228	        let _ = sqlx::query!(
229	            r#"UPDATE reporting.report_runs
230	               SET status = 'failed', completed_at = now()
231	               WHERE id = $1"#,
232	            run_id
233	        )
234	        .execute(pool)
235	        .await;
236	    } else {
237	        let _ = sqlx::query!(
238	            r#"UPDATE reporting.report_runs
239	               SET status = 'completed', result_data = $2, completed_at = now()
240	               WHERE id = $1"#,
241	            run_id,
242	            result_json,
243	        )
244	        .execute(pool)
245	        .await;
246	    }
247	
248	    // Advance `next_run_at` and update `last_run_at`
249	    let next = next_run_at(&report.schedule, now);
250	    let _ = sqlx::query!(
251	        r#"UPDATE reporting.scheduled_reports
252	           SET next_run_at = $2, last_run_at = now(), updated_at = now()
253	           WHERE id = $1"#,
254	        report.id,
255	        next,
256	    )
257	    .execute(pool)
258	    .await;
259	}
