265	/// Compute the next `next_run_at` timestamp for a given schedule string.
266	///
267	/// - `"daily"`   → `now + 1 day`
268	/// - `"weekly"`  → `now + 7 days`
269	/// - `"monthly"` → `now + 30 days` (simple approximation)
270	fn next_run_at(schedule: &str, from: chrono::DateTime<Utc>) -> chrono::DateTime<Utc> {
