use async_trait::async_trait;
use sqlx::PgPool;

use crate::reporting::scheduler as report_scheduler;
use crate::scheduler::{Job, JobError, JobOutcome};

/// Fires due scheduled reports every 60 seconds.
///
/// Per tick:
///   1. SELECT all `scheduled_reports` WHERE `is_active = TRUE AND next_run_at <= now()`
///      using `FOR UPDATE SKIP LOCKED` to prevent double-execution.
///   2. For each due report: compute all listed metrics, write a `report_runs` row,
///      advance `next_run_at` to the next occurrence.
///
/// Idempotency:
///   `FOR UPDATE SKIP LOCKED` prevents another instance from picking up the same
///   report in the same tick.  The `report_runs` row is inserted in `running` state
///   before computation begins, so a crash leaves a `running` record that can be
///   inspected and re-triggered manually.
pub struct ReportGenerationJob;

#[async_trait]
impl Job for ReportGenerationJob {
    fn name(&self) -> &'static str { "report_generation" }

    fn interval(&self) -> Duration { Duration::from_secs(60) }

    async fn run(&self, pool: &PgPool) -> Result<JobOutcome, JobError> {
        report_scheduler::tick(pool).await?;
        Ok(JobOutcome {
            summary: serde_json::json!({ "action": "scheduled_reports_evaluated" }),
        })
    }
}
"}

