    // Must be spawned before the HTTP server so it starts processing immediately.
    tokio::spawn(notifications::bus::run_event_bus(pool.clone(), adapter_registry));

    // Background report scheduler — checks for due scheduled reports every 60 s.
    tokio::spawn(reporting::scheduler::run_report_scheduler(pool.clone()));

    // Background payment compensation sweeps — run every 15 minutes.
    // Handles stuck transactions, pending refunds, and unprocessed callbacks.
    tokio::spawn(payments::compensation::run_compensation_scheduler(pool.clone()));

    // Background KPI anomaly checker — evaluates metric snapshots every 30 minutes
    // and creates alerting.alerts rows when deviation exceeds the configured threshold.
    tokio::spawn(alerting::detector::run_kpi_anomaly_scheduler(pool));", "new_string": "    // ── Background job scheduler ──────────────────────────────────────────────
    // Creates a pool-backed scheduler, repairs any stale `running` records from
    // a previous crash, then registers all jobs as independent tokio tasks.
    //
    // Graceful shutdown: when the HTTP server stops (SIGTERM / Ctrl-C), main()
    // returns, the tokio runtime drops, and all tasks are cancelled.  Jobs that
    // are currently sleeping exit within ~500 ms.  In-flight jobs complete first.
    {
        use scheduler::{Scheduler, jobs::{
            notification_bus::NotificationBusJob,
            payment_compensation::PaymentCompensationJob,
            report_generation::ReportGenerationJob,
            kpi_anomaly::KpiAnomalyJob,
            scheduled_config::ScheduledConfigJob,
            dedup_cleanup::DedupCleanupJob,
        }};

        let sched = Scheduler::new(pool.clone());

        if let Err(e) = sched.recover_stale_runs().await {
            tracing::warn!(error = %e, "Could not recover stale job_runs records");
        }

        // 5 s — event fan-out, DND flush, keyword/spike rule evaluation
        sched.spawn(NotificationBusJob { adapters: adapter_registry });

        // 15 min — stuck transactions, stuck refunds, unprocessed callbacks
        sched.spawn(PaymentCompensationJob);

        // 60 s — fire scheduled_reports whose next_run_at has passed
        sched.spawn(ReportGenerationJob);

        // 30 min — compare KPI snapshots against rolling average, raise alerts
        sched.spawn(KpiAnomalyJob);

        // 60 s — publish ops.config_versions with effective_from <= now();
        //         activate rollout stages with scheduled_at <= now()
        sched.spawn(ScheduledConfigJob);

        // 1 h — prune job_runs (7 d), channel_deliveries (30 d), dismissed
