     1	/// Signature verification and anti-replay protection.
     2	///
     3	/// ## Signed-string construction
     4	///
     5	/// The string passed to HMAC is: `nonce + "." + timestamp_str + "." + body_sha256_hex`
     6	/// (timestamp component omitted when `ts_in_sig = false`).
     7	///
     8	/// This mirrors the pattern used by Stripe/Alipay-style webhooks.
     9	///
    10	/// ## Anti-replay strategy
    11	///
    12	/// Two independent checks, both must pass:
    13	///   1. **Timestamp window** — provider timestamp must be within ±300 seconds of now.
    14	///      Prevents attackers who captured a valid request from replaying it later.
    15	///   2. **Nonce uniqueness** — nonce must not already exist in `payments.callbacks`.
    16	///      Prevents exact-duplicate replays within the timestamp window.
    17	use chrono::Utc;
    18	use hmac::{Hmac, Mac};
    19	use sha2::{Digest, Sha256, Sha512};
    20	use sqlx::PgPool;
    21	
    22	use super::gateway::PaymentGateway;
    23	
    24	// ============================================================
    25	// Error type
    26	// ============================================================
    27	
    28	#[derive(Debug, thiserror::Error, PartialEq)]
    29	pub enum ReplayError {
    30	    #[error("Timestamp out of window: {0} seconds from now (max 300)")]
    31	    TimestampStale(i64),
    32	
    33	    #[error("Nonce '{0}' has already been used")]
    34	    NonceReused(String),
    35	}
    36	
    37	// ============================================================
    38	// HMAC computation
    39	// ============================================================
    40	
    41	/// Compute HMAC-SHA256 of `message` with `secret`, returning a lower-case hex string.
    42	pub fn hmac_sha256_hex(secret: &[u8], message: &[u8]) -> String {
    43	    type HmacSha256 = Hmac<Sha256>;
    44	    let mut mac = HmacSha256::new_from_slice(secret)
    45	        .expect("HMAC-SHA256 accepts any key length");
    46	    mac.update(message);
    47	    hex::encode(mac.finalize().into_bytes())
    48	}
    49	
    50	/// Compute HMAC-SHA512 of `message` with `secret`, returning a lower-case hex string.
    51	pub fn hmac_sha512_hex(secret: &[u8], message: &[u8]) -> String {
    52	    type HmacSha512 = Hmac<Sha512>;
    53	    let mut mac = HmacSha512::new_from_slice(secret)
    54	        .expect("HMAC-SHA512 accepts any key length");
    55	    mac.update(message);
    56	    hex::encode(mac.finalize().into_bytes())
    57	}
    58	
    59	/// SHA-256 of arbitrary bytes, hex-encoded.
    60	pub fn sha256_hex(data: &[u8]) -> String {
    61	    let mut hasher = Sha256::new();
    62	    hasher.update(data);
    63	    hex::encode(hasher.finalize())
    64	}
    65	
    66	// ============================================================
    67	// Signed-string construction
    68	// ============================================================
    69	
    70	/// Build the canonical string that the provider signs.
    71	///
    72	/// Format: `nonce.timestamp.body_hash`   (or `nonce.body_hash` if `ts_in_sig = false`)
    73	pub fn build_signed_string(nonce: &str, timestamp: i64, body: &[u8], ts_in_sig: bool) -> String {
    74	    let body_hash = sha256_hex(body);
    75	    if ts_in_sig {
    76	        format!("{}.{}.{}", nonce, timestamp, body_hash)
    77	    } else {
    78	        format!("{}.{}", nonce, body_hash)
    79	    }
    80	}
    81	
    82	// ============================================================
    83	// Full verification pipeline
    84	// ============================================================
    85	
    86	/// Verify an inbound callback signature and anti-replay constraints.
    87	///
    88	/// Steps:
    89	///   1. Validate timestamp is within 5-minute window.
    90	///   2. Validate nonce has not been used (DB look-up).
    91	///   3. Reconstruct signed string and verify HMAC.
    92	///
    93	/// Returns `Ok(())` if all checks pass, or the first failing error.
    94	pub async fn verify_callback(
    95	    pool:          &PgPool,
    96	    gateway:       &dyn PaymentGateway,
    97	    raw_body:      &[u8],
    98	    nonce:         &str,
    99	    timestamp:     i64,
   100	    provided_sig:  &str,
   101	) -> Result<(), VerifyError> {
   102	    // 1. Timestamp window
   103	    validate_timestamp(timestamp)?;
   104	
   105	    // 2. Nonce uniqueness
   106	    check_nonce_fresh(pool, nonce).await?;
   107	
   108	    // 3. HMAC
   109	    let signed = build_signed_string(nonce, timestamp, raw_body, gateway.ts_in_sig());
   110	    let expected = match gateway.hmac_algorithm() {
   111	        "sha512" => hmac_sha512_hex(gateway.hmac_secret_bytes(), signed.as_bytes()),
   112	        _        => hmac_sha256_hex(gateway.hmac_secret_bytes(), signed.as_bytes()),
   113	    };
   114	
   115	    // Constant-time comparison to prevent timing attacks
   116	    if !constant_time_eq(provided_sig.as_bytes(), expected.as_bytes()) {
   117	        return Err(VerifyError::BadSignature);
   118	    }
   119	
   120	    Ok(())
   121	}
   122	
   123	/// Combined error type for the full verification pipeline.
   124	#[derive(Debug, thiserror::Error)]
   125	pub enum VerifyError {
   126	    #[error("Replay detected: {0}")]
   127	    Replay(#[from] ReplayError),
   128	
   129	    #[error("Signature mismatch")]
   130	    BadSignature,
   131	
   132	    #[error("Database error during nonce check: {0}")]
   133	    Db(#[from] sqlx::Error),
   134	}
   135	
   136	impl From<VerifyError> for crate::error::AppError {
   137	    fn from(e: VerifyError) -> Self {
   138	        match e {
   139	            VerifyError::Replay(_)     => crate::error::AppError::BadRequest(e.to_string()),
   140	            VerifyError::BadSignature  => crate::error::AppError::Unauthorized(
   141	                "Callback signature verification failed".to_string(),
   142	            ),
   143	            VerifyError::Db(db)        => crate::error::AppError::Database(db),
   144	        }
   145	    }
   146	}
   147	
   148	// ============================================================
   149	// Timestamp validation
   150	// ============================================================
   151	
   152	/// Maximum age (seconds) before a callback timestamp is rejected.
   153	pub const MAX_TIMESTAMP_SKEW_SECS: i64 = 300; // 5 minutes
   154	
   155	/// Reject if the provider-reported timestamp deviates from `now()` by more than 5 minutes.
   156	pub fn validate_timestamp(ts_secs: i64) -> Result<(), ReplayError> {
   157	    let now = Utc::now().timestamp();
   158	    let delta = (now - ts_secs).abs();
   159	    if delta > MAX_TIMESTAMP_SKEW_SECS {
   160	        Err(ReplayError::TimestampStale(delta))
   161	    } else {
   162	        Ok(())
   163	    }
   164	}
   165	
   166	// ============================================================
   167	// Nonce freshness
   168	// ============================================================
   169	
   170	/// Check that `nonce` does not already exist in `payments.callbacks`.
   171	///
   172	/// The `callbacks.nonce` column has a UNIQUE constraint that acts as a DB-level
   173	/// backstop, but we also check here to return a clear error before attempting
   174	/// the INSERT.
   175	pub async fn check_nonce_fresh(pool: &PgPool, nonce: &str) -> Result<(), ReplayError> {
   176	    let exists: bool = sqlx::query_scalar!(
   177	        "SELECT EXISTS(SELECT 1 FROM payments.callbacks WHERE nonce = $1)",
   178	        nonce,
   179	    )
   180	    .fetch_one(pool)
   181	    .await
   182	    .ok()
   183	    .flatten()
   184	    .unwrap_or(false);
   185	
   186	    if exists {
   187	        Err(ReplayError::NonceReused(nonce.to_string()))
   188	    } else {
   189	        Ok(())
   190	    }
   191	}
   192	
   193	// ============================================================
   194	// Constant-time comparison
   195	// ============================================================
   196	
   197	/// Constant-time byte-slice equality to prevent timing attacks on HMAC comparison.
   198	fn constant_time_eq(a: &[u8], b: &[u8]) -> bool {
   199	    if a.len() != b.len() {
   200	        return false;
   201	    }
   202	    let mut diff: u8 = 0;
   203	    for (x, y) in a.iter().zip(b.iter()) {
   204	        diff |= x ^ y;
   205	    }
   206	    diff == 0
   207	}
   208	
   209	// ============================================================
   210	// Tests
   211	// ============================================================
   212	#[cfg(test)]
   213	mod tests {
   214	    use super::*;
   215	
   216	    #[test]
   217	    fn hmac_sha256_is_deterministic() {
   218	        let sig1 = hmac_sha256_hex(b"secret", b"hello");
   219	        let sig2 = hmac_sha256_hex(b"secret", b"hello");
   220	        assert_eq!(sig1, sig2);
   221	    }
   222	
   223	    #[test]
   224	    fn hmac_sha256_differs_with_different_key() {
   225	        let sig1 = hmac_sha256_hex(b"key1", b"hello");
   226	        let sig2 = hmac_sha256_hex(b"key2", b"hello");
   227	        assert_ne!(sig1, sig2);
   228	    }
   229	
   230	    #[test]
   231	    fn signed_string_includes_timestamp() {
   232	        let s = build_signed_string("nonce123", 1700000000, b"body", true);
   233	        assert!(s.starts_with("nonce123.1700000000."));
   234	    }
   235	
   236	    #[test]
   237	    fn signed_string_omits_timestamp_when_flag_false() {
   238	        let s = build_signed_string("nonce123", 1700000000, b"body", false);
   239	        assert!(s.starts_with("nonce123."));
   240	        assert!(!s.contains("1700000000"));
   241	    }
   242	
   243	    #[test]
   244	    fn validate_timestamp_accepts_recent() {
   245	        let now = Utc::now().timestamp();
   246	        assert!(validate_timestamp(now).is_ok());
   247	        assert!(validate_timestamp(now - 100).is_ok());
   248	        assert!(validate_timestamp(now + 100).is_ok());
   249	    }
   250	
   251	    #[test]
   252	    fn validate_timestamp_rejects_stale() {
   253	        let now = Utc::now().timestamp();
   254	        let err = validate_timestamp(now - 400).unwrap_err();
   255	        assert!(matches!(err, ReplayError::TimestampStale(_)));
   256	    }
   257	
   258	    #[test]
   259	    fn validate_timestamp_rejects_future() {
   260	        let now = Utc::now().timestamp();
   261	        let err = validate_timestamp(now + 400).unwrap_err();
   262	        assert!(matches!(err, ReplayError::TimestampStale(_)));
   263	    }
   264	
   265	    #[test]
   266	    fn constant_time_eq_works() {
   267	        assert!(constant_time_eq(b"hello", b"hello"));
   268	        assert!(!constant_time_eq(b"hello", b"world"));
   269	        assert!(!constant_time_eq(b"hello", b"hi"));
   270	    }
   271	
   272	    #[test]
   273	    fn sha256_hex_is_correct() {
   274	        // SHA-256("") = e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855
   275	        let h = sha256_hex(b"");
   276	        assert_eq!(&h[..8], "e3b0c442");
   277	    }
   278	}
