     1	/// Discrepancy detection logic.
     2	///
     3	/// This module answers two questions independently of any database:
     4	///   1. Which statement records are duplicates of each other?
     5	///   2. What discrepancy type applies to a (DB amount, statement amount) pair?
     6	use std::collections::HashMap;
     7	
     8	use super::models::{DiscrepancyType, StatementRecord};
     9	
    10	// ============================================================
    11	// Tolerance constant
    12	// ============================================================
    13	
    14	/// Maximum permitted difference between DB amount and statement amount for
    15	/// a pair to be classified as `matched`.  Anything strictly greater than this
    16	/// is `amount_mismatch`.
    17	pub const AMOUNT_TOLERANCE: f64 = 0.01; // $0.01
    18	
    19	// ============================================================
    20	// Duplicate detection
    21	// ============================================================
    22	
    23	/// Group statement records by `reference` and identify duplicates.
    24	///
    25	/// Returns a map from each reference that appears **more than once** to the
    26	/// indices of all rows carrying that reference.  References appearing exactly
    27	/// once are not included in the map.
    28	///
    29	/// # Example
    30	/// ```
    31	/// // ["TXN001", "TXN002", "TXN001"]  →  {"TXN001": [0, 2]}
    32	/// ```
    33	pub fn find_duplicates<'a>(records: &'a [StatementRecord]) -> HashMap<&'a str, Vec<usize>> {
    34	    let mut groups: HashMap<&str, Vec<usize>> = HashMap::new();
    35	    for (i, rec) in records.iter().enumerate() {
    36	        groups.entry(rec.reference.as_str()).or_default().push(i);
    37	    }
    38	    groups.retain(|_, indices| indices.len() > 1);
    39	    groups
    40	}
    41	
    42	/// Returns `true` if the record at `idx` is considered a duplicate
    43	/// (i.e. its reference appears more than once in the full record set).
    44	pub fn is_duplicate(idx: usize, dup_map: &HashMap<&str, Vec<usize>>) -> bool {
    45	    dup_map.values().any(|indices| indices.contains(&idx))
    46	}
    47	
    48	/// For duplicate groups, the first occurrence (lowest index) is considered the
    49	/// canonical entry; all others are the duplicates.
    50	pub fn canonical_index(indices: &[usize]) -> usize {
    51	    *indices.iter().min().expect("non-empty")
    52	}
    53	
    54	// ============================================================
    55	// Amount comparison
    56	// ============================================================
    57	
    58	/// Classify the relationship between a DB-side expected amount and a
    59	/// statement-side actual amount.
    60	///
    61	/// Assumes both amounts are non-negative and the pair has already been matched
    62	/// on transaction reference (i.e. they refer to the same transaction).
    63	pub fn classify_amounts(expected: f64, actual: f64) -> DiscrepancyType {
    64	    if (expected - actual).abs() <= AMOUNT_TOLERANCE {
    65	        DiscrepancyType::Matched
    66	    } else {
    67	        DiscrepancyType::AmountMismatch
    68	    }
    69	}
    70	
    71	/// Compute the net financial discrepancy: `actual − expected`.
    72	///
    73	/// Positive → over-collected.  Negative → under-collected.
    74	pub fn net_discrepancy(expected: f64, actual: f64) -> f64 {
    75	    actual - expected
    76	}
    77	
    78	// ============================================================
    79	// Discrepancy summary
    80	// ============================================================
    81	
    82	/// Counts across all discrepancy types in a run.
    83	#[derive(Debug, Default)]
    84	pub struct DiscrepancySummary {
    85	    pub matched:               usize,
    86	    pub amount_mismatches:     usize,
    87	    pub missing_from_statement: usize,
    88	    pub extra_in_statement:    usize,
    89	    pub duplicates:            usize,
    90	}
    91	
    92	impl DiscrepancySummary {
    93	    pub fn total_discrepancies(&self) -> usize {
    94	        self.amount_mismatches
    95	            + self.missing_from_statement
    96	            + self.extra_in_statement
    97	            + self.duplicates
    98	    }
    99	
   100	    pub fn is_clean(&self) -> bool { self.total_discrepancies() == 0 }
   101	
   102	    /// Returns true when discrepancy count exceeds 10 or 5% of total records.
   103	    pub fn is_high(&self, total_records: usize) -> bool {
   104	        let n = self.total_discrepancies();
   105	        n > 10 || (total_records > 0 && n * 100 / total_records > 5)
   106	    }
   107	}
   108	
   109	// ============================================================
   110	// Tests
   111	// ============================================================
   112	#[cfg(test)]
   113	mod tests {
   114	    use super::*;
   115	    use chrono::NaiveDate;
   116	    use super::super::models::EntryType;
   117	
   118	    fn rec(r: &str) -> StatementRecord {
   119	        StatementRecord {
   120	            reference:   r.to_string(),
   121	            amount:      100.0,
   122	            entry_type:  EntryType::Credit,
   123	            date:        NaiveDate::from_ymd_opt(2025, 1, 15).unwrap(),
   124	            description: None,
   125	        }
   126	    }
   127	
   128	    #[test]
   129	    fn no_duplicates_returns_empty_map() {
   130	        let records = vec![rec("A"), rec("B"), rec("C")];
   131	        let dups = find_duplicates(&records);
   132	        assert!(dups.is_empty());
   133	    }
   134	
   135	    #[test]
   136	    fn single_duplicate_pair_detected() {
   137	        let records = vec![rec("A"), rec("B"), rec("A")];
   138	        let dups = find_duplicates(&records);
   139	        assert_eq!(dups.len(), 1);
   140	        assert!(dups.contains_key("A"));
   141	        assert_eq!(dups["A"], vec![0, 2]);
   142	    }
   143	
   144	    #[test]
   145	    fn triple_occurrence_detected() {
   146	        let records = vec![rec("X"), rec("X"), rec("X"), rec("Y")];
   147	        let dups = find_duplicates(&records);
   148	        assert_eq!(dups["X"].len(), 3);
   149	    }
   150	
   151	    #[test]
   152	    fn canonical_index_is_first() {
   153	        assert_eq!(canonical_index(&[3, 1, 5]), 1);
   154	    }
   155	
   156	    #[test]
   157	    fn classify_amounts_within_tolerance() {
   158	        assert_eq!(classify_amounts(100.00, 100.00), DiscrepancyType::Matched);
   159	        assert_eq!(classify_amounts(100.00, 100.01), DiscrepancyType::Matched);
   160	        assert_eq!(classify_amounts(100.00,  99.99), DiscrepancyType::Matched);
   161	    }
   162	
   163	    #[test]
   164	    fn classify_amounts_exceeds_tolerance() {
   165	        assert_eq!(classify_amounts(100.00, 100.02), DiscrepancyType::AmountMismatch);
   166	        assert_eq!(classify_amounts(100.00,  99.98), DiscrepancyType::AmountMismatch);
   167	    }
   168	
   169	    #[test]
   170	    fn net_discrepancy_positive_and_negative() {
   171	        assert!((net_discrepancy(100.0, 120.0) -  20.0).abs() < 1e-9);
   172	        assert!((net_discrepancy(100.0,  80.0) - -20.0).abs() < 1e-9);
   173	    }
   174	
   175	    #[test]
   176	    fn summary_high_discrepancy_count() {
   177	        let s = DiscrepancySummary {
   178	            matched: 5,
   179	            amount_mismatches: 11,
