     1	/// Per-job execution engine: advisory lock → run → record outcome.
     2	///
     3	/// Advisory lock semantics
     4	/// ───────────────────────
     5	/// `pg_try_advisory_lock($1)` acquires a session-level exclusive lock identified
     6	/// by a 64-bit integer.  It is:
     7	///   • Non-blocking — returns false immediately if already held.
     8	///   • Session-scoped — automatically released when the connection is closed
     9	///     (i.e. when the process crashes), so no cleanup query is needed on restart.
    10	///   • In-memory — no table write; negligible overhead even on 5-second intervals.
    11	///
    12	/// The lock ID is derived from the job name via FNV-1a, giving a stable mapping
    13	/// that survives restarts without a lock table.
    14	use std::sync::Arc;
    15	use std::time::Instant;
    16	use sqlx::PgPool;
    17	use uuid::Uuid;
    18	
    19	use super::{Job, JobError, ShutdownFlag};
    20	
    21	// ── Main loop ─────────────────────────────────────────────────────────────────
    22	
    23	/// Runs a job on its configured interval until `shutdown` is signalled.
    24	/// Sleep is broken into 500 ms increments so shutdown is detected promptly.
    25	pub async fn job_loop(pool: PgPool, job: Arc<dyn Job>, shutdown: ShutdownFlag) {
    26	    tracing::info!(job = job.name(), interval_secs = job.interval().as_secs(), "Job loop started");
    27	
    28	    loop {
    29	        if shutdown.is_set() {
    30	            break;
    31	        }
    32	
    33	        execute(&pool, &job).await;
    34	
    35	        // Sleep in small slices so we react to shutdown within ~500 ms.
    36	        let deadline = tokio::time::Instant::now() + job.interval();
    37	        loop {
    38	            if shutdown.is_set() {
    39	                tracing::info!(job = job.name(), "Job loop exiting (shutdown)");
    40	                return;
    41	            }
    42	            let remaining = deadline.saturating_duration_since(tokio::time::Instant::now());
    43	            if remaining.is_zero() {
    44	                break;
    45	            }
    46	            tokio::time::sleep(remaining.min(std::time::Duration::from_millis(500))).await;
    47	        }
    48	    }
    49	
    50	    tracing::info!(job = job.name(), "Job loop stopped");
    51	}
    52	
    53	// ── Single execution ──────────────────────────────────────────────────────────
    54	
    55	async fn execute(pool: &PgPool, job: &Arc<dyn Job>) {
    56	    let lock_id = advisory_lock_id(job.name());
    57	
    58	    // Try to acquire — non-blocking
    59	    let acquired: bool = match sqlx::query_scalar("SELECT pg_try_advisory_lock($1)")
    60	        .bind(lock_id)
    61	        .fetch_one(pool)
    62	        .await
    63	    {
    64	        Ok(b)  => b,
    65	        Err(e) => {
    66	            tracing::warn!(job = job.name(), error = %e, "Advisory lock query failed, skipping tick");
    67	            return;
