   102	
   103	async fn record_start(pool: &PgPool, job_name: &str) -> Option<Uuid> {
   104	    match sqlx::query_scalar(
   105	        "INSERT INTO scheduler.job_runs (job_name, status) VALUES ($1, 'running') RETURNING id",
   106	    )
   107	    .bind(job_name)
   108	    .fetch_one(pool)
   109	    .await
   110	    {
   111	        Ok(id) => Some(id),
   112	        Err(e) => {
   113	            tracing::warn!(job = job_name, error = %e, "Failed to create job_run record");
   114	            None
   115	        }
   116	    }
   117	}
   118	
   119	async fn record_finish(
   120	    pool:   &PgPool,
   121	    run_id: Uuid,
   122	    ms:     i32,
   123	    result: Result<super::JobOutcome, JobError>,
   124	) {
   125	    let (status, outcome, error_msg): (&str, Option<serde_json::Value>, Option<String>) =
   126	        match result {
   127	            Ok(o) => {
   128	                tracing::info!(
   129	                    run_id  = %run_id,
   130	                    ms,
   131	                    outcome = %o.summary,
   132	                    "Job succeeded"
   133	                );
   134	                ("success", Some(o.summary), None)
   135	            }
   136	            Err(e) => {
   137	                tracing::error!(run_id = %run_id, ms, error = %e, "Job failed");
   138	                ("failed", None, Some(e.to_string()))
   139	            }
   140	        };
   141	
   142	    let _ = sqlx::query(
   143	        r#"UPDATE scheduler.job_runs
   144	           SET    status      = $2,
   145	                  finished_at = now(),
   146	                  duration_ms = $3,
   147	                  outcome     = $4,
   148	                  error_msg   = $5
   149	           WHERE  id = $1"#,
   150	    )
   151	    .bind(run_id)
   152	    .bind(status)
   153	    .bind(ms)
   154	    .bind(outcome)
   155	    .bind(error_msg)
   156	    .execute(pool)
   157	    .await
   158	    .map_err(|e| tracing::warn!(run_id = %run_id, error = %e, "Failed to update job_run record"));
   159	}
   160	
   161	// ── Lock ID ───────────────────────────────────────────────────────────────────
   162	
   163	/// Derive a stable i64 advisory lock identifier from a job name using FNV-1a.
   164	/// The output is deterministic and collision-resistant for short ASCII strings.
   165	pub fn advisory_lock_id(name: &str) -> i64 {
   166	    const OFFSET: u64 = 14_695_981_039_346_656_037;
   167	    const PRIME:  u64 = 1_099_511_628_211;
   168	    let mut h = OFFSET;
   169	    for b in name.bytes() {
   170	        h ^= b as u64;
   171	        h = h.wrapping_mul(PRIME);
   172	    }
   173	    h as i64
   174	}
   175	
   176	#[cfg(test)]
   177	mod tests {
   178	    use super::advisory_lock_id;
   179	
   180	    #[test]
   181	    fn lock_ids_are_deterministic() {
   182	        assert_eq!(advisory_lock_id("notification_bus"), advisory_lock_id("notification_bus"));
   183	    }
   184	
   185	    #[test]
   186	    fn different_names_differ() {
   187	        assert_ne!(
   188	            advisory_lock_id("payment_compensation"),
   189	            advisory_lock_id("report_generation")
   190	        );
   191	    }
   192	}
