/// Background job scheduler.
///
/// ## Design
///
/// Each registered job runs in its own dedicated tokio task on a fixed interval.
/// A shared `ShutdownFlag` lets `main()` ask all loops to exit cleanly after
/// their current sleep completes — no in-flight work is ever interrupted.
///
/// ## Execution guarantees
///
/// **At-least-once with strong deduplication** via PostgreSQL advisory locks:
///
/// | Scenario                                            | Outcome                    |
/// |-----------------------------------------------------|----------------------------|
/// | Normal operation                                    | Exactly-once per interval  |
/// | Second process starts (rolling deploy)              | Skip — lock held elsewhere |
/// | Process crashes mid-job                             | PG releases lock on session close; next instance retries |
/// | `job_runs` INSERT fails (transient DB error)        | Job still runs; logged as "unrecorded" |
/// | `job_runs` UPDATE fails after successful run        | Status stays `running`; repaired on restart by `recover_stale_runs` |
///
/// Advisory lock IDs are derived from the job name with FNV-1a so they are
/// stable across restarts without requiring a lock table.
///
/// ## Idempotency requirement
///
/// Because the guarantee is at-least-once, **every job must be idempotent**.
/// The individual jobs achieve this via:
/// - `FOR UPDATE SKIP LOCKED` on the rows they process
/// - Status guards (`WHERE status = 'pending'`, `WHERE processed_at IS NULL`)
/// - Upserts with `ON CONFLICT DO NOTHING / DO UPDATE`
pub mod executor;
pub mod jobs;

use std::sync::{
    Arc,
---
/// Anomaly alerting module.
///
/// Provides lifecycle-tracked alerts sourced from reconciliation mismatches
/// and KPI deviations, with severity levels and an acknowledge / close workflow.
///
/// ## Detection sources
///
///   - **Reconciliation mismatches** — triggered synchronously by the reconciliation
///     engine after each run that contains discrepancies.
///   - **KPI anomalies** — evaluated asynchronously by a background task every
///     30 minutes; compares latest metric snapshot against a rolling baseline.
///
/// ## Alert lifecycle
///
/// ```text
///   open → acknowledged → closed
///   open →               closed
/// ```
///
/// ## Route tree  (`/alerts`)
///
/// ```text
/// GET  /alerts            list_alerts   (filters: status, severity, alert_type)
/// GET  /alerts/stats      alert_stats   (aggregated counts — dashboard widget)
/// GET  /alerts/{id}       get_alert
/// POST /alerts/{id}/acknowledge
/// POST /alerts/{id}/close
/// ```
pub mod detector;
pub mod handlers;
pub mod models;

use actix_web::web;

use handlers::{acknowledge_alert, alert_stats, close_alert, get_alert, list_alerts};

/// Register all `/alerts` routes onto the Actix-web `ServiceConfig`.
///
/// Static paths (`/stats`, `/{id}/acknowledge`, `/{id}/close`) are registered
/// before the bare `/{id}` resource to prevent Actix-web route shadowing.
pub fn configure_routes(cfg: &mut web::ServiceConfig) {
    cfg.service(
        web::scope("/alerts")
            // ── Collection ────────────────────────────────────────────────────
            .service(
                web::resource("")
                    .route(web::get().to(list_alerts)),
            )
            // ── Aggregated stats (static, before /{id}) ───────────────────────
            .service(
                web::resource("/stats")
                    .route(web::get().to(alert_stats)),
            )
            // ── Workflow sub-paths (static, before /{id}) ─────────────────────
            .service(
                web::resource("/{id}/acknowledge")
                    .route(web::post().to(acknowledge_alert)),
            )
            .service(
                web::resource("/{id}/close")
                    .route(web::post().to(close_alert)),
            )
            // ── Single resource (after static sub-paths) ──────────────────────
            .service(
                web::resource("/{id}")
                    .route(web::get().to(get_alert)),
            ),
    );
}
