// async fn different_entity_creates_independent_alert() {
//     // Setup: open alert for UUID-A
//     // Call create_alert for UUID-B (same alert_type)
//     // Assert: new alert row for UUID-B, no conflict with UUID-A
// }

// #[tokio::test]
